/**
 * Bible Book 48: கலாத்தியர் (Galatians)
 */
if (typeof window.registerBibleBook === 'function') {
  window.registerBibleBook(48, {"id": 48, "testament": "NT", "code": "GAL", "name_en": "Galatians", "name_ta": "கலாத்தியர்", "category": "Pauline Epistles", "category_ta": "பவுலின் நிருபங்கள்", "total_chapters": 6, "chapters": {"1": {"chapter": 1, "duration": 221.97, "audio_url": "audio_nt/B09_01.mp3", "total_verses": 24, "verses": [{"verse": 1, "start": 4.8, "end": 15.33, "ta": "மனுஷராலுமல்ல, மனுஷன் மூலமாயுமல்ல, இயேசுகிறிஸ்துவினாலும், அவரை மரித்தோரிலிருந்தெழுப்பின பிதாவாகிய தேவனாலும், அப்போஸ்தலனாயிருக்கிற பவுலாகிய நானும்,", "en": "Paul, an apostle, (not of men, neither by man, but by Jesus Christ, and God the Father, who raised him from the dead;)"}, {"verse": 2, "start": 15.33, "end": 21.13, "ta": "என்னுடனேகூட இருக்கிற சகோதரரெல்லாரும், கலாத்தியா நாட்டிலுள்ள சபைகளுக்கு எழுதுகிறதாவது:", "en": "And all the brethren which are with me, unto the churches of Galatia:"}, {"verse": 3, "start": 21.13, "end": 28.89, "ta": "பிதாவாகிய தேவனாலும், நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவினாலும் உங்களுக்குக் கிருபையும் சமாதானமும் உண்டாவதாக;", "en": "Grace be to you and peace from God the Father, and from our Lord Jesus Christ,"}, {"verse": 4, "start": 28.89, "end": 40.48, "ta": "அவர் நம்மை இப்பொழுதிருக்கிற பொல்லாத பிரபஞ்சத்தினின்று விடுவிக்கும்படி நம்முடைய பிதாவாகிய தேவனுடைய சித்தத்தின்படியே நம்முடைய பாவங்களுக்காகத் தம்மைத்தாமே ஒப்புக்கொடுத்தார்;", "en": "Who gave himself for our sins, that he might deliver us from this present evil world, according to the will of God and our Father:"}, {"verse": 5, "start": 40.48, "end": 45.42, "ta": "அவருக்கு என்றென்றைக்குமுள்ள சதாகாலங்களிலும் மகிமை உண்டாவதாக ஆமென்.", "en": "To whom be glory for ever and ever. Amen."}, {"verse": 6, "start": 45.42, "end": 55.95, "ta": "உங்களைக் கிறிஸ்துவின் கிருபையினாலே அழைத்தவரை நீங்கள் இவ்வளவு சீக்கிரமாய் விட்டு, வேறொரு சுவிசேஷத்திற்குத் திரும்புகிறதைப்பற்றி நான் ஆச்சரியப்படுகிறேன்;", "en": "I marvel that ye are so soon removed from him that called you into the grace of Christ unto another gospel:"}, {"verse": 7, "start": 55.95, "end": 65.37, "ta": "வேறொரு சுவிசேஷம் இல்லையே; சிலர் உங்களைக் கலகப்படுத்தி, கிறிஸ்துவிடைய சுவிசேஷத்தைப் புரட்ட மனதாயிருக்கிறார்களேயல்லாமல் வேறல்ல.", "en": "Which is not another; but there be some that trouble you, and would pervert the gospel of Christ."}, {"verse": 8, "start": 65.37, "end": 78.99, "ta": "நாங்கள் உங்களுக்குப் பிரசங்கித்த சுவிசேஷத்தையல்லாமல், நாங்களாவது, வானத்திலிருந்து வருகிற ஒரு தூதனாவது, வேறொரு சுவிசேஷத்தை உங்களுக்குப் பிரசங்கித்தால், அவன் சபிக்கப்பட்டவனாயிருக்கக்கடவன்.", "en": "But though we, or an angel from heaven, preach any other gospel unto you than that which we have preached unto you, let him be accursed."}, {"verse": 9, "start": 78.99, "end": 91.24, "ta": "முன் சொன்னதுபோல மறுபடியும் சொல்லுகிறேன்; நீங்கள் ஏற்றுக்கொண்ட சுவிசேஷத்தையல்லாமல் வேறொரு சுவிசேஷத்தை ஒருவன் உங்களுக்குப் பிரசங்கித்தால் அவன் சபிக்கப்பட்டவனாயிருக்கக்கடவன்.", "en": "As we said before, so say I now again, If any man preach any other gospel unto you than that ye have received, let him be accursed."}, {"verse": 10, "start": 91.24, "end": 105.66, "ta": "இப்பொழுது நான் மனுஷரையா, தேவனையா, யாரை நாடிப் போதிக்கிறேன்? மனுஷரையா பிரியப்படுத்தப் பார்க்கிறேன்? நான் இன்னும் மனுஷரைப் பிரியப்படுத்துகிறவனாயிருந்தால் நான் கிறிஸ்துவின் ஊழியக்காரனல்லவே.", "en": "For do I now persuade men, or God? or do I seek to please men? for if I yet pleased men, I should not be the servant of Christ."}, {"verse": 11, "start": 105.66, "end": 114.35, "ta": "மேலும், சகோதரரே, என்னால் பிரசங்கிக்கப்பட்ட சுவிசேஷம் மனுஷருடைய யோசனையின்படியானதல்லவென்று உங்களுக்குத் தெரிவிக்கிறேன்.", "en": "But I certify you, brethren, that the gospel which was preached of me is not after man."}, {"verse": 12, "start": 114.35, "end": 122.25, "ta": "நான் அதை ஒரு மனுஷனால் பெற்றதுமில்லை, மனுஷனால் கற்றதுமில்லை, இயேசுகிறிஸ்துவே அதை எனக்கு வெளிப்படுத்தினார்.", "en": "For I neither received it of man, neither was I taught it , but by the revelation of Jesus Christ."}, {"verse": 13, "start": 122.25, "end": 132.85, "ta": "நான் யூதமார்க்கத்திலிருந்தபோது என்னுடைய நடக்கையைக்குறித்துக் கேள்விப்பட்டிருப்பீர்கள்; தேவனுடைய சபையை நான் மிகவும் துன்பப்படுத்தி, அதைப் பாழாக்கி;", "en": "For ye have heard of my conversation in time past in the Jews’ religion, how that beyond measure I persecuted the church of God, and wasted it:"}, {"verse": 14, "start": 132.85, "end": 144.24, "ta": "என் ஜனத்தாரில் என் வயதுள்ள அநேகரைப்பார்க்கிலும் யூதமார்க்கத்திலே தேறினவனாய், என் பிதாக்களுடைய பாரம்பரிய நியாயங்களுக்காக மிகவும் பக்திவைராக்கியமுள்ளவனாயிருந்தேன்.", "en": "And profited in the Jews’ religion above many my equals in mine own nation, being more exceedingly zealous of the traditions of my fathers."}, {"verse": 15, "start": 144.24, "end": 152.73, "ta": "அப்படியிருந்தும், நான் என் தாயின் வயிற்றிலிருந்தது முதல், என்னைப் பிரித்தெடுத்து, தம்முடைய கிருபையினால் அழைத்த தேவன்,", "en": "But when it pleased God, who separated me from my mother’s womb, and called me by his grace,"}, {"verse": 16, "start": 152.73, "end": 165.17, "ta": "தம்முடைய குமாரனை நான் புறஜாதிகளிடத்தில் சுவிசேஷமாய் அறிவிக்கும்பொருட்டாக, அவரை எனக்குள் வெளிப்படுத்தப் பிரியமாயிருந்தபோது, உடனே நான் மாம்சத்தோடும் இரத்தத்தோடும் யோசனைபண்ணாமலும்;", "en": "To reveal his Son in me, that I might preach him among the heathen; immediately I conferred not with flesh and blood:"}, {"verse": 17, "start": 165.17, "end": 175.9, "ta": "எனக்கு முன்னே அப்போஸ்தலரானவர்களிடத்திலே எருசலேமுக்குப்போகாமலும்; அரபிதேசத்திற்குப் புறப்பட்டுப்போய், மறுபடியும் தமஸ்கு ஊருக்குத் திரும்பிவந்தேன்.", "en": "Neither went I up to Jerusalem to them which were apostles before me; but I went into Arabia, and returned again unto Damascus."}, {"verse": 18, "start": 175.9, "end": 185.12, "ta": "மூன்று வருஷம் சென்ற பின்பு, பேதுருவைக் கண்டுகொள்ளும்படி நான் எருசலேமுக்குப் போய், அவனிடத்தில் பதினைந்து நாள் தங்கியிருந்தேன்.", "en": "Then after three years I went up to Jerusalem to see Peter, and abode with him fifteen days."}, {"verse": 19, "start": 185.12, "end": 191.37, "ta": "கர்த்தருடைய சகோதரனாகிய யாக்கோபைத் தவிர, அப்போஸ்தலரில் வேறொருவரையும் நான் காணவில்லை.", "en": "But other of the apostles saw I none, save James the Lord’s brother."}, {"verse": 20, "start": 191.37, "end": 197.89, "ta": "நான் உங்களுக்கு எழுதுகிற இவைகள் பொய்யல்லவென்று தேவனுக்குமுன்பாக நிச்சயமாய்ச் சொல்லுகிறேன்.", "en": "Now the things which I write unto you, behold, before God, I lie not."}, {"verse": 21, "start": 197.89, "end": 202.17, "ta": "பின்பு, சீரியா சிலிசியா நாடுகளின் புறங்களில் வந்தேன்.", "en": "Afterwards I came into the regions of Syria and Cilicia;"}, {"verse": 22, "start": 202.17, "end": 207.83, "ta": "மேலும் யூதேயாதேசத்திலே கிறிஸ்துவுக்குள்ளான சபைகளுக்கு முகமறியாதவனாயிருந்தேன்.", "en": "And was unknown by face unto the churches of Judaea which were in Christ:"}, {"verse": 23, "start": 207.83, "end": 217.18, "ta": "முன்னே நம்மைத் துன்பப்படுத்தினவனே, தான் அழிக்கத்தேடின விசுவாசத்தை இப்பொழுது பிரசங்கிக்கிறானென்பதை மாத்திரம் அவர்கள் கேள்விப்பட்டிருந்து,", "en": "But they had heard only, That he which persecuted us in times past now preacheth the faith which once he destroyed."}, {"verse": 24, "start": 217.18, "end": 220.47, "ta": "என்னைப்பற்றி தேவனை மகிமைப்படுத்தினார்கள்.", "en": "And they glorified God in me."}]}, "2": {"chapter": 2, "duration": 254.37, "audio_url": "audio_nt/B09_02.mp3", "total_verses": 21, "verses": [{"verse": 1, "start": 3.8, "end": 11.59, "ta": "பதினாலு வருஷம் சென்றபின்பு, நான் தீத்துவைக் கூட்டிக்கொண்டு பர்னபாவுடனேகூட மறுபடியும் எருசலேமுக்குப் போனேன்.", "en": "Then fourteen years after I went up again to Jerusalem with Barnabas, and took Titus with me also."}, {"verse": 2, "start": 11.59, "end": 27.7, "ta": "நான் தேவ அறிவிப்பினாலே போய், புறஜாதிகளிடத்தில் நான் பிரசங்கிக்கிற சுவிசேஷத்தை அவர்களுக்கு விவரித்துக் காண்பித்தேன்; ஆயினும் நான் ஓடுகிறதும், ஓடினதும் வீணாகாதபடிக்கு எண்ணிக்கையுள்ளவர்களுக்கே தனிமையாய் விவரித்துக் காண்பித்தேன்.", "en": "And I went up by revelation, and communicated unto them that gospel which I preach among the Gentiles, but privately to them which were of reputation, lest by any means I should run, or had run, in vain."}, {"verse": 3, "start": 27.7, "end": 35.82, "ta": "ஆனாலும் என்னுடனேகூட இருந்த தீத்து கிரேக்கனாயிருந்தும் விருத்தசேதனம்பண்ணிக்கொள்ளும்படிக்குக் கட்டாயம்பண்ணப்படவில்லை.", "en": "But neither Titus, who was with me, being a Greek, was compelled to be circumcised:"}, {"verse": 4, "start": 35.82, "end": 48.0, "ta": "கிறிஸ்து இயேசுவுக்குள் நமக்கு உண்டான சுயாதீனத்தை உளவுபார்த்து நம்மை நியாயப்பிரமாரணத்திற்கு அடிமைகளாக்கும்பொருட்டாகப் பக்கவழியாய் நுழைந்த கள்ளச் சகோதரர் நிமித்தம் அப்படியாயிற்று.", "en": "And that because of false brethren unawares brought in, who came in privily to spy out our liberty which we have in Christ Jesus, that they might bring us into bondage:"}, {"verse": 5, "start": 48.0, "end": 56.97, "ta": "சுவிசேஷத்தின் சத்தியம் உங்களிடத்திலே நிலைத்திருக்கும்படி, நாங்கள் ஒரு நாழிகையாகிலும் அவர்களுக்குக் கீழ்ப்படிந்து இணங்கவில்லை.", "en": "To whom we gave place by subjection, no, not for an hour; that the truth of the gospel might continue with you."}, {"verse": 6, "start": 56.97, "end": 69.6, "ta": "அல்லாமலும் எண்ணிக்கையுள்ளவர்களாயிருந்தவர்கள் எனக்கு ஒன்றும் போதிக்கவில்லை; அவர்கள் எப்படிப்பட்டவர்களாயிருந்தாலும் எனக்குக் கவலையில்லை, தேவன் மனுஷரிடத்தில் பட்சபாதமுள்ளவரல்லவே.", "en": "But of these who seemed to be somewhat, (whatsoever they were, it maketh no matter to me: God accepteth no man’s person:) for they who seemed to be somewhat in conference added nothing to me:"}, {"verse": 7, "start": 69.6, "end": 80.73, "ta": "அதுவுமல்லாமல், விருத்தசேதனமுள்ளவர்களுக்கு அப்போஸ்தலனாயிருக்கும்படி பேதுருவைப் பலப்படுத்தினவர் புறஜாதிகளுக்கு அப்போஸ்தலனாயிருக்கும்படி என்னையும் பலப்படுத்தினபடியால்,", "en": "But contrariwise, when they saw that the gospel of the uncircumcision was committed unto me, as the gospel of the circumcision was unto Peter;"}, {"verse": 8, "start": 80.73, "end": 94.29, "ta": "விருத்தசேதனமுள்ள அவர்களுக்குச் சுவிசேஷத்தைப் பிரசங்கிக்கும்படி பேதுருவுக்குக் கையளிக்கப்பட்டதுபோல, விருத்தசேதனம் இல்லாதவர்களுக்குப் பிரசங்கிக்கும்படி அது எனக்கும் கையளிக்கப்பட்டதென்று அவர்கள் கண்டு;", "en": "(For he that wrought effectually in Peter to the apostleship of the circumcision, the same was mighty in me toward the Gentiles:)"}, {"verse": 9, "start": 94.29, "end": 112.23, "ta": "எனக்கு அளிக்கப்பட்ட கிருபையை அறிந்தபோது, தூண்களாக எண்ணப்பட்ட யாக்கோபும், கேபாவும், யோவானும், தாங்கள் விருத்தசேதனமுள்ளவர்களுக்கும், நாங்கள் புறஜாதிகளுக்கும் பிரசங்கிக்கும்படி, அந்நியோந்நிய ஐக்கியத்திற்கு அடையாளமாக எனக்கும் பர்னபாவுக்கும் வலதுகை கொடுத்து,", "en": "And when James, Cephas, and John, who seemed to be pillars, perceived the grace that was given unto me, they gave to me and Barnabas the right hands of fellowship; that we should go unto the heathen, and they unto the circumcision."}, {"verse": 10, "start": 112.23, "end": 121.46, "ta": "தரித்திரரை நினைத்துக்கொள்ளும்படிக்குமாத்திரம் சொன்னார்கள்; அப்படிச் செய்யும்படி அதற்கு முன்னமே நானும் கருத்துள்ளவனாயிருந்தேன்.", "en": "Only they would that we should remember the poor; the same which I also was forward to do."}, {"verse": 11, "start": 121.46, "end": 129.71, "ta": "மேலும், பேதுரு அந்தியோகியாவுக்கு வந்தபோது, அவன்மேல் குற்றஞ்சுமந்ததினால், நான் முகமுகமாய் அவனோடே எதிர்த்தேன்.", "en": "But when Peter was come to Antioch, I withstood him to the face, because he was to be blamed."}, {"verse": 12, "start": 129.71, "end": 142.28, "ta": "எப்படியெனில், யாக்கோபினிடத்திலிருந்து சிலர் வருகிறதற்குமுன் அவன் புறஜாதியாருடனே சாப்பிட்டான்; அவர்கள் வந்தபோதோ, விருத்தசேதனமுள்ளவர்களுக்குப் பயந்து, விலகிப் பிரிந்தான்.", "en": "For before that certain came from James, he did eat with the Gentiles: but when they were come, he withdrew and separated himself, fearing them which were of the circumcision."}, {"verse": 13, "start": 142.28, "end": 149.22, "ta": "மற்ற யூதரும் அவனுடனேகூட மாயம்பண்ணினார்கள்; அவர்களுடைய மாயத்தினாலே பர்னபாவும் இழுப்புண்டான்.", "en": "And the other Jews dissembled likewise with him; insomuch that Barnabas also was carried away with their dissimulation."}, {"verse": 14, "start": 149.22, "end": 170.24, "ta": "இப்படி அவர்கள் சுவிசேஷத்தின் சத்தியத்திற்கேற்றபடி சரியாய் நடவாததை நான் கண்டபோது, எல்லாருக்கும் முன்பாக நான் பேதுருவை நோக்கிச்சொன்னது என்னவென்றால்: யூதனாயிருக்கிற நீர் யூதர் முறைமையாக நடவாமல், புறஜாதியார் முறைமையாக நடந்துகொண்டிருக்க, புறஜாதியாரை யூதர்முறைமையாக நடக்கும்படி நீர் எப்படிக்கட்டாயம் பண்ணலாம்?", "en": "But when I saw that they walked not uprightly according to the truth of the gospel, I said unto Peter before them all, If thou, being a Jew, livest after the manner of Gentiles, and not as do the Jews, why compellest thou the Gentiles to live as do the Jews?"}, {"verse": 15, "start": 170.24, "end": 194.14, "ta": "புறஜாதியாரில் பிறந்த பாவிகளாயிராமல், சுபாவத்தின்படி யூதராயிருக்கிற நாமும் இயேசுகிறிஸ்துவைப்பற்றும் விசுவாசத்தினாலேயன்றி, நியாயப்பிரமாணத்தின் கிரியைகளினாலே மனுஷன் நீதிமானாக்கப்படுவதில்லையென்று அறிந்து, நியாயப்பிரமாணத்தின் கிரியைகளினாலல்ல, கிறிஸ்துவைப்பற்றும் விசுவாசத்தினாலே நீதிமான்களாக்கப்படும்படிக்குக் கிறிஸ்து இயேசுவின்மேல் விசுவாசிகளானோம்.", "en": "We who are Jews by nature, and not sinners of the Gentiles,"}, {"verse": 16, "start": 194.14, "end": 199.57, "ta": "நியாயப்பிரமாணத்தின் கிரியைகளினாலே எந்த மனுஷனும் நீதிமானாக்கப்படுவதில்லையே.", "en": "Knowing that a man is not justified by the works of the law, but by the faith of Jesus Christ, even we have believed in Jesus Christ, that we might be justified by the faith of Christ, and not by the works of the law: for by the works of the law shall no flesh be justified."}, {"verse": 17, "start": 199.57, "end": 209.07, "ta": "கிறிஸ்துவுக்குள் நீதிமான்களாக்கப்படும்படி நாடுகிற நாமும் பாவிகளாகக் காணப்படுவோமானால், கிறிஸ்து பாவத்திற்குக் காரணரோ? அல்லவே.", "en": "But if, while we seek to be justified by Christ, we ourselves also are found sinners, is therefore Christ the minister of sin? God forbid."}, {"verse": 18, "start": 209.07, "end": 215.94, "ta": "நான் இடித்துப்போட்டவைகளையே நான் மறுபடியும் கட்டினால், பிரமாணத்தை மீறுகிறவனென்று காணப்படுவேன்.", "en": "For if I build again the things which I destroyed, I make myself a transgressor."}, {"verse": 19, "start": 215.94, "end": 222.23, "ta": "தேவனுக்கென்று பிழைக்கும்படி நான் நியாயப்பிரமாணத்தினாலே நியாயப்பிரமாணத்திற்கு மரித்தேனே.", "en": "For I through the law am dead to the law, that I might live unto God."}, {"verse": 20, "start": 222.23, "end": 243.7, "ta": "கிறிஸ்துவுடனேகூடச் சிலுவையிலறையப்பட்டேன்; ஆயினும், பிழைத்திருக்கிறேன்; இனி நான் அல்ல, கிறிஸ்துவே எனக்குள் பிழைத்திருக்கிறார்; நான் இப்பொழுது மாம்சத்தில் பிழைத்திருக்கிறதோ, என்னில் அன்புகூர்ந்து எனக்காகத் தம்மைத்தாமே ஒப்புக்கொடுத்த தேவனுடைய குமாரனைப்பற்றும் விசுவாசத்தினாலே பிழைத்திருக்கிறேன்.", "en": "I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me."}, {"verse": 21, "start": 243.7, "end": 252.87, "ta": "நான் தேவனுடைய கிருபையை விருதாவாக்குகிறதில்லை; நீதியானது நியாயப்பிரமாணத்தினாலே வருமானால், கிறிஸ்து மரித்தது வீணாயிருக்குமே.", "en": "I do not frustrate the grace of God: for if righteousness come by the law, then Christ is dead in vain."}]}, "3": {"chapter": 3, "duration": 311.61, "audio_url": "audio_nt/B09_03.mp3", "total_verses": 29, "verses": [{"verse": 1, "start": 3.8, "end": 20.11, "ta": "புத்தியில்லாத கலாத்தியரே, நீங்கள் சத்தியத்திற்குக் கீழ்ப்படியாமற்போகத்தக்கதாக உங்களை மயக்கினவன் யார்? இயேசுகிறிஸ்து சிலுவையிலறையப்பட்டவராக உங்கள் கண்களுக்குமுன் பிரத்தியட்சமாய் உங்களுக்குள்ளே வெளிப்படுத்தப்பட்டிருந்தாரே.", "en": "O foolish Galatians, who hath bewitched you, that ye should not obey the truth, before whose eyes Jesus Christ hath been evidently set forth, crucified among you?"}, {"verse": 2, "start": 20.11, "end": 31.01, "ta": "ஒன்றைமாத்திரம் உங்களிடத்தில் அறியவிரும்புகிறேன்; நியாயப்பிரமாணத்தின் கிரியைகளினாலேயோ, விசுவாசக் கேள்வியினாலேயோ, எதினாலே ஆவியைப் பெற்றீர்கள்?", "en": "This only would I learn of you, Received ye the Spirit by the works of the law, or by the hearing of faith?"}, {"verse": 3, "start": 31.01, "end": 39.47, "ta": "ஆவியினாலே ஆரம்பம்பண்ணின நீங்கள் இப்பொழுது மாம்சத்தினாலே முடிவுபெறப்போகிறீர்களோ? நீங்கள் இத்தனை புத்தியீனரா?", "en": "Are ye so foolish? having begun in the Spirit, are ye now made perfect by the flesh?"}, {"verse": 4, "start": 39.47, "end": 45.02, "ta": "இத்தனை பாடுகளையும் வீணாய்ப் பட்டீர்களோ? அவைகள் வீணாய்ப்போயிற்றே.", "en": "Have ye suffered so many things in vain? if it be yet in vain."}, {"verse": 5, "start": 45.02, "end": 57.35, "ta": "அன்றியும் உங்களுக்கு ஆவியை அளித்து, உங்களுக்குள்ளே அற்புதங்களை நடப்பிக்கிறவர் அதை நியாயப்பிரமாணத்தின் கிரியைகளினாலேயோ, விசுவாசக் கேள்வியினாலேயோ, எதினாலே செய்கிறார்?", "en": "He therefore that ministereth to you the Spirit, and worketh miracles among you, doeth he it by the works of the law, or by the hearing of faith?"}, {"verse": 6, "start": 57.35, "end": 63.17, "ta": "அப்படியே ஆபிரகாம் தேவனை விசுவாசித்தான், அது அவனுக்கு நீதியாக எண்ணப்பட்டது.", "en": "Even as Abraham believed God, and it was accounted to him for righteousness."}, {"verse": 7, "start": 63.17, "end": 69.53, "ta": "ஆகையால் விசுவாசமார்க்கத்தார்கள் எவர்களோ அவர்களே ஆபிரகாமின் பிள்ளைகளென்று அறிவீர்களாக.", "en": "Know ye therefore that they which are of faith, the same are the children of Abraham."}, {"verse": 8, "start": 69.53, "end": 82.26, "ta": "மேலும் தேவன் விசுவாசத்தினாலே புறஜாதிகளை நீதிமான்களாக்குகிறாரென்று வேதம் முன்னாகக் கண்டு: உனக்குள் சகல ஜாதிகளும் ஆசீர்வதிக்கப்படும் என்று ஆபிரகாமுக்குச் சுவிசேஷமாய் முன்னறிவித்தது.", "en": "And the scripture, foreseeing that God would justify the heathen through faith, preached before the gospel unto Abraham, saying , In thee shall all nations be blessed."}, {"verse": 9, "start": 82.26, "end": 88.42, "ta": "அந்தப்படி விசுவாசமார்க்கத்தார் விசுவாசமுள்ள ஆபிரகாமுடனே ஆசீர்வதிக்கப்படுகிறார்கள்.", "en": "So then they which be of faith are blessed with faithful Abraham."}, {"verse": 10, "start": 88.42, "end": 104.12, "ta": "நியாயப்பிரமாணத்தின் கிரியைக்காரராகிய யாவரும் சாபத்திற்குட்பட்டிருக்கிறார்கள்; நியாயப்பிரமாண புஸ்தகத்தில் எழுதப்பட்டவைகளையெல்லாம் செய்யத்தக்கதாக அவைகளில் நிலைத்திராதவன் எவனோ அவன் சபிக்கப்பட்டவன் என்று எழுதியிருக்கிறதே.", "en": "For as many as are of the works of the law are under the curse: for it is written, Cursed is every one that continueth not in all things which are written in the book of the law to do them."}, {"verse": 11, "start": 104.12, "end": 116.44, "ta": "நியாயப்பிரமாணத்தினாலே ஒருவனும் தேவனிடத்தில் நீதிமானாகிறதில்லையென்பது வெளியரங்கமாயிருக்கிறது. ஏனெனில், விசுவாசத்தினாலே நீதிமான் பிழைப்பான் என்று எழுதியிருக்கிறதே.", "en": "But that no man is justified by the law in the sight of God, it is evident: for, The just shall live by faith."}, {"verse": 12, "start": 116.44, "end": 123.14, "ta": "நியாயப்பிரமாணமோ விசுவாசத்திற்குரியதல்ல; அவைகளைச் செய்கிற மனுஷனே அவைகளால் பிழைப்பான்.", "en": "And the law is not of faith: but, The man that doeth them shall live in them."}, {"verse": 13, "start": 123.14, "end": 135.19, "ta": "மரத்திலே தூக்கப்பட்ட எவனும் சபிக்கப்பட்டவன் என்று எழுதியிருக்கிறபடி, கிறிஸ்து நமக்காகச் சாபமாகி, நியாயப்பிரமாணத்தின் சாபத்திற்கு நம்மை நீங்லாக்கி மீட்டுக்கொண்டார்.", "en": "Christ hath redeemed us from the curse of the law, being made a curse for us: for it is written, Cursed is every one that hangeth on a tree:"}, {"verse": 14, "start": 135.19, "end": 148.46, "ta": "ஆபிரகாமுக்கு உண்டான ஆசீர்வாதம் கிறிஸ்து இயேசுவினால் புறஜாதிகளுக்கு வரும்படியாகவும், ஆவியைக்குறித்துச் சொல்லப்பட்ட வாக்குத்தத்தத்தை நாம் விசுவாசத்தினாலே பெறும்படியாகவும் இப்படியாயிற்று.", "en": "That the blessing of Abraham might come on the Gentiles through Jesus Christ; that we might receive the promise of the Spirit through faith."}, {"verse": 15, "start": 148.46, "end": 160.37, "ta": "சகோதரரே, மனுஷர் முறைமையின்படி சொல்லுகிறேன்; மனுஷர்களுக்குள்ளே உறுதிபண்ணப்பட்ட உடன்படிக்கையை ஒருவனும் தள்ளுகிறதுமில்லை, அதினோடே ஒன்றையும் கூட்டுகிறதுமில்லை.", "en": "Brethren, I speak after the manner of men; Though it be but a man’s covenant, yet if it be confirmed, no man disannulleth, or addeth thereto."}, {"verse": 16, "start": 160.37, "end": 175.47, "ta": "ஆபிரகாமுக்கும் அவனுடைய சந்ததிக்கும் வாக்குத்தத்தங்கள் பண்ணப்பட்டன; சந்ததிகளுக்கு என்று அநேகரைக்குறித்துச் சொல்லாமல், உன் சந்ததிக்கு என்று ஒருவனைக்குறித்துச் சொல்லியிருக்கிறார், அந்தச் சந்ததி கிறிஸ்துவே.", "en": "Now to Abraham and his seed were the promises made. He saith not, And to seeds, as of many; but as of one, And to thy seed, which is Christ."}, {"verse": 17, "start": 175.47, "end": 190.56, "ta": "ஆதலால் நான் சொல்லுகிறதென்னவெனில், கிறிஸ்துவை முன்னிட்டு தேவனால் முன் உறுதிபண்ணப்பட்ட உடன்படிக்கையை நானூற்றுமுப்பது வருஷத்திற்குப்பின்பு உண்டான நியாயப்பிரமாணமானது தள்ளி, வாக்குத்தத்தத்தை வியர்த்தமாக்கமாட்டாது.", "en": "And this I say, that the covenant, that was confirmed before of God in Christ, the law, which was four hundred and thirty years after, cannot disannul, that it should make the promise of none effect."}, {"verse": 18, "start": 190.56, "end": 202.21, "ta": "அன்றியும், சுதந்தரமானது நியாயப்பிரமாணத்தினாலே உண்டானால் அது வாக்குத்தத்தத்தினாலே உண்டாயிராது; தேவன் அதை ஆபிரகாமுக்கு வாக்குத்தத்தத்தினாலே அருளிச்செய்தாரே.", "en": "For if the inheritance be of the law, it is no more of promise: but God gave it to Abraham by promise."}, {"verse": 19, "start": 202.21, "end": 216.29, "ta": "அப்படியானால், நியாயப்பிரமாணத்தின் நோக்கமென்ன? வாக்குத்தத்தத்தைப்பெற்ற சந்ததி வருமளவும் அது அக்கிரமங்களினிமித்தமாகக் கூட்டப்பட்டு, தேவதூதரைக்கொண்டு மத்தியஸ்தன் கையிலே கட்டளையிடப்பட்டது.", "en": "Wherefore then serveth the law? It was added because of transgressions, till the seed should come to whom the promise was made; and it was ordained by angels in the hand of a mediator."}, {"verse": 20, "start": 216.29, "end": 220.15, "ta": "மத்தியஸ்தன் ஒருவனுக்குரியவனல்ல, தேவனோ ஒருவர்.", "en": "Now a mediator is not a mediator of one, but God is one."}, {"verse": 21, "start": 220.15, "end": 234.9, "ta": "அப்படியானால், நியாயப்பிரமாணம் தேவனுடைய வாக்குத்தத்தங்களுக்கு விரோதமா? அல்லவே; உயிரைக் கொடுக்கத்தக்க நியாயப்பிரமாணம் அருளப்பட்டிருந்ததானால், நீதியானது நியாயப்பிரமாணத்தினால் உண்டாயிருக்குமே.", "en": "Is the law then against the promises of God? God forbid: for if there had been a law given which could have given life, verily righteousness should have been by the law."}, {"verse": 22, "start": 234.9, "end": 248.17, "ta": "அப்படியிராதபடியால், இயேசுகிறிஸ்துவைப் பற்றும் விசுவாசத்தினாலே பலிக்கிற வாக்குத்தத்தம் விசுவாசமுள்ளவர்களுக்கு அளிக்கப்படும்படி வேதம் எல்லாரையும் ஏகமாய்ப் பாவத்தின்கீழ் அடைத்துப்போட்டது.", "en": "But the scripture hath concluded all under sin, that the promise by faith of Jesus Christ might be given to them that believe."}, {"verse": 23, "start": 248.17, "end": 259.21, "ta": "ஆதலால் விசுவாசம் வருகிறதற்குமுன்னே, வெளிப்படப்போகிற விசுவாசத்திற்கு ஏதுவாக நாம் அடைக்கப்பட்டவர்களாய் நியாயப்பிரமாணத்தின்கீழ் காவல் பண்ணப்பட்டிருந்தோம்.", "en": "But before faith came, we were kept under the law, shut up unto the faith which should afterwards be revealed."}, {"verse": 24, "start": 259.21, "end": 269.09, "ta": "இவ்விதமாக, நாம் விசுவாசத்திலே நீதிமான்களாக்கப்படுவதற்கு நியாயப்பிரமாணம் நம்மைக் கிறிஸ்துவினிடத்தில் வழிநடத்துகிற உபாத்தியாய் இருந்தது.", "en": "Wherefore the law was our schoolmaster to bring us unto Christ, that we might be justified by faith."}, {"verse": 25, "start": 269.09, "end": 273.49, "ta": "விசுவாசம் வந்தபின்பு நாம் உபாத்திக்குக் கீழானவர்களல்லவே.", "en": "But after that faith is come, we are no longer under a schoolmaster."}, {"verse": 26, "start": 273.49, "end": 280.33, "ta": "நீங்களெல்லாரும் கிறிஸ்து இயேசுவைப்பற்றும் விசுவாசத்தினால் தேவனுடைய புத்திரராயிருக்கிறீர்களே.", "en": "For ye are all the children of God by faith in Christ Jesus."}, {"verse": 27, "start": 280.33, "end": 289.46, "ta": "ஏனெனில், உங்களில் கிறிஸ்துவுக்குள்ளாக, ஞானஸ்நானம் பெற்றவர்கள் எத்தனைபேரோ அத்தனைபேரும் கிறிஸ்துவைத் தரித்துக்கொண்டீர்களே.", "en": "For as many of you as have been baptized into Christ have put on Christ."}, {"verse": 28, "start": 289.46, "end": 301.45, "ta": "யூதனென்றும் கிரேக்கனென்றுமில்லை, அடிமையென்றும் சுயாதீனனென்றுமில்லை, ஆணென்றும் பெண்ணென்றுமில்லை; நீங்களெல்லாரும் கிறிஸ்து இயேசுவுக்குள் ஒன்றாயிருக்கிறீர்கள்.", "en": "There is neither Jew nor Greek, there is neither bond nor free, there is neither male nor female: for ye are all one in Christ Jesus."}, {"verse": 29, "start": 301.45, "end": 310.11, "ta": "நீங்கள் கிறிஸ்துவினுடையவர்களானால், ஆபிரகாமின் சந்ததியாராயும், வாக்குத்தத்தத்தின்படியே சுதந்தரராயுமிருக்கிறீர்கள்.", "en": "And if ye be Christ’s, then are ye Abraham’s seed, and heirs according to the promise."}]}, "4": {"chapter": 4, "duration": 291.6, "audio_url": "audio_nt/B09_04.mp3", "total_verses": 31, "verses": [{"verse": 1, "start": 3.8, "end": 16.17, "ta": "பின்னும் நான் சொல்லுகிறதென்னவெனில், சுதந்தரவாளியானவன் எல்லாவற்றிற்கும் எஜமானாயிருந்தும், அவன் சிறுபிள்ளையாயிருக்குங்காலமளவும், அவனுக்கும் அடிமையானவனுக்கும் வித்தியாசமில்லை.", "en": "Now I say, That the heir, as long as he is a child, differeth nothing from a servant, though he be lord of all;"}, {"verse": 2, "start": 16.17, "end": 23.6, "ta": "தகப்பன் குறித்த காலம்வரைக்கும் அவன் காரியக்காரருக்கும் வீட்டு விசாரணைக்காரருக்கும் கீழ்ப்பட்டிருக்கிறான்.", "en": "But is under tutors and governors until the time appointed of the father."}, {"verse": 3, "start": 23.6, "end": 30.96, "ta": "அப்படியே நாமும் சிறுபிள்ளைகளாயிருந்த காலத்தில் இவ்வுலகத்தின் வழிபாடுகளுக்கு அடிமைப்பட்டவர்களாயிருந்தோம்.", "en": "Even so we, when we were children, were in bondage under the elements of the world:"}, {"verse": 4, "start": 30.96, "end": 37.54, "ta": "நாம் புத்திரசுவிகாரத்தையடையும்படி நியாயப்பிரமாணத்திற்குக் கீழ்ப்பட்டவர்களை மீட்டுக்கொள்ளத்தக்கதாக,", "en": "But when the fulness of the time was come, God sent forth his Son, made of a woman, made under the law,"}, {"verse": 5, "start": 37.54, "end": 46.39, "ta": "காலம் நிறைவேறினபோது, ஸ்திரீயினிடத்திற் பிறந்தவரும் நியாயப்பிரமாணத்திற்குக் கீழானவருமாகிய தம்முடைய குமாரனை தேவன் அனுப்பினார்.", "en": "To redeem them that were under the law, that we might receive the adoption of sons."}, {"verse": 6, "start": 46.39, "end": 56.62, "ta": "மேலும் நீங்கள் புத்திரராயிருக்கிறபடியினால், அப்பா, பிதாவே! என்று கூப்பிடத்தக்கதாக தேவன் தமது குமாரனுடைய ஆவியை உங்கள் இருதயங்களில் அனுப்பினார்.", "en": "And because ye are sons, God hath sent forth the Spirit of his Son into your hearts, crying, Abba, Father."}, {"verse": 7, "start": 56.62, "end": 65.74, "ta": "ஆகையால் இனி நீ அடிமையாயிராமல் புத்திரனாயிருக்கிறாய்; நீ புத்திரனேயானால், கிறிஸ்துமூலமாய் தேவனுடைய சுதந்தரனாயுமிருக்கிறாய்.", "en": "Wherefore thou art no more a servant, but a son; and if a son, then an heir of God through Christ."}, {"verse": 8, "start": 65.74, "end": 72.57, "ta": "நீங்கள் தேவனை அறியாமலிருந்தபோது, சுபாவத்தின்படி தேவர்களல்லாதவர்களுக்கு அடிமைகளாயிருந்தீர்கள்.", "en": "Howbeit then, when ye knew not God, ye did service unto them which by nature are no gods."}, {"verse": 9, "start": 72.57, "end": 86.9, "ta": "இப்பொழுதோ நீங்கள் தேவனை அறிந்திருக்க, அல்லது தேவனாலே அறியப்பட்டிருக்க, பெலனற்றதும் வெறுமையானதுமான அவ்வழிபாடுகளுக்கு நீங்கள் மறுபடியும் திரும்பி, மறுபடியும் அவைகளுக்கு அடிமைப்படும்படி விரும்புகிறதெப்படி?", "en": "But now, after that ye have known God, or rather are known of God, how turn ye again to the weak and beggarly elements, whereunto ye desire again to be in bondage?"}, {"verse": 10, "start": 86.9, "end": 92.63, "ta": "நாட்களையும், மாதங்களையும், காலங்ளையும், வருஷங்களையும் பார்க்கிறீர்களே.", "en": "Ye observe days, and months, and times, and years."}, {"verse": 11, "start": 92.63, "end": 99.28, "ta": "நான் உங்களுக்காகப் பிரயாசப்பட்டது வீணாய்ப்போயிற்றோ என்று உங்களைக்குறித்துப் பயந்திருக்கிறேன்.", "en": "I am afraid of you, lest I have bestowed upon you labour in vain."}, {"verse": 12, "start": 99.28, "end": 109.31, "ta": "சகோதரர் என்னைப்போலாகுங்கள் என்று உங்களை வேண்டிக்கொள்ளுகிறேன்; நான் உங்களைப்போலுமானேனே. எனக்கு நீங்கள் அநியாயம் ஒன்றும்செய்யவில்லை.", "en": "Brethren, I beseech you, be as I am ; for I am as ye are : ye have not injured me at all."}, {"verse": 13, "start": 109.31, "end": 117.19, "ta": "உங்களுக்குத் தெரிந்திருக்கிறபடி, நான் சரீர பலவீனத்தோடு முதலாந்தரம் உங்களுக்குச் சுவிசேஷத்தைப் பிரசங்கித்தேன்.", "en": "Ye know how through infirmity of the flesh I preached the gospel unto you at the first."}, {"verse": 14, "start": 117.19, "end": 129.24, "ta": "அப்படியிருந்தும் என் சரீரத்திலுண்டாயிருக்கிற சோதனையை நீங்கள் அசட்டைபண்ணாமலும், அரோசியாமலும், தேவதூதனைப்போலவும், கிறிஸ்து இயேசுவைப்போலவும், என்னை ஏற்றுக்கொண்டீர்கள்.", "en": "And my temptation which was in my flesh ye despised not, nor rejected; but received me as an angel of God, even as Christ Jesus."}, {"verse": 15, "start": 129.24, "end": 142.0, "ta": "அப்பொழுது நீங்கள் கொண்டிருந்த ஆனந்த பாக்கியம் எங்கே? உங்கள் கண்களைப் பிடுங்கி எனக்குக் கொடுக்கக்கூடுமானால், அப்படியும் செய்திருப்பீர்களென்று உங்களுக்குச் சாட்சியாயிருக்கிறேன்.", "en": "Where is then the blessedness ye spake of? for I bear you record, that, if it had been possible, ye would have plucked out your own eyes, and have given them to me."}, {"verse": 16, "start": 142.0, "end": 147.15, "ta": "நான் உங்களுக்குச் சத்தியத்தைச் சொன்னதினாலே உங்களுக்குச் சத்துருவானேனோ?", "en": "Am I therefore become your enemy, because I tell you the truth?"}, {"verse": 17, "start": 147.15, "end": 159.78, "ta": "அவர்கள் உங்களை நாடி வைராக்கியம் பாராட்டுகிறார்கள், ஆகிலும் நல்மனதோடே அப்படிச் செய்யாமல், நீங்கள் அவர்களை நாடி வைராக்கியம் பாராட்டும்பொருட்டு உங்களைப் புறம்பாக்க விரும்புகிறார்கள்.", "en": "They zealously affect you, but not well; yea, they would exclude you, that ye might affect them."}, {"verse": 18, "start": 159.78, "end": 169.29, "ta": "நல்விஷயத்தில் வைராக்கியம் பராட்டுவது நல்லதுதான்; அதை நான் உங்களிடத்தில் இருக்கும்பொழுதுமாத்திரமல்ல, எப்பொழுதும் பாராட்டவேண்டும்.", "en": "But it is good to be zealously affected always in a good thing , and not only when I am present with you."}, {"verse": 19, "start": 169.29, "end": 176.71, "ta": "என் சிறுபிள்ளைகளே, கிறிஸ்து உங்களிடத்தில் உருவாகுமளவும் உங்களுக்காக மறுபடியும் கர்ப்பவேதனைப்படுகிறேன்.", "en": "My little children, of whom I travail in birth again until Christ be formed in you,"}, {"verse": 20, "start": 176.71, "end": 185.44, "ta": "உங்களைக்குறித்து நான் சந்தேகப்படுகிறபடியால், நான் இப்பொழுது உங்களிடத்தில் வந்திருந்து, வேறுவகையாகப் பேச விரும்புகிறேன்.", "en": "I desire to be present with you now, and to change my voice; for I stand in doubt of you."}, {"verse": 21, "start": 185.44, "end": 195.14, "ta": "நியாயப்பிரமாணத்திற்குக் கீழ்ப்பட்டிருக்க விரும்புகிற நீங்கள் நியாயப்பிரமாணம் சொல்லுகிறதைக் கேட்கவில்லையா? இதை எனக்குச் சொல்லுங்கள்.", "en": "Tell me, ye that desire to be under the law, do ye not hear the law?"}, {"verse": 22, "start": 195.14, "end": 205.56, "ta": "ஆபிரகாமுக்கு இரண்டு குமாரர் இருந்தார்கள் என்று எழுதியிருக்கிறது; ஒருவன் அடிமையானவளிடத்தில் பிறந்தவன், ஒருவன் சுயாதீனமுள்ளவளிடத்தில் பிறந்தவன்.", "en": "For it is written, that Abraham had two sons, the one by a bondmaid, the other by a freewoman."}, {"verse": 23, "start": 205.56, "end": 214.16, "ta": "அடிமையானவளிடத்தில் பிறந்தவன் மாம்சத்தின்படி பிறந்தான், சுயாதீனமுள்ளவளிடத்தில் பிறந்தவன் வாக்குத்தத்தத்தின்படி பிறந்தான்.", "en": "But he who was of the bondwoman was born after the flesh; but he of the freewoman was by promise."}, {"verse": 24, "start": 214.16, "end": 226.8, "ta": "இவைகள் ஞான அர்த்தமுள்ளவைகள்; அந்த ஸ்திரீகள் இரண்டு ஏற்பாடுகளாம்; ஒன்று சீனாய்மலையிலுண்டான ஏற்பாடு, அது அடிமைத்தனத்திற்குள்ளாகப் பிள்ளைபெறுகிறது, அது ஆகார் என்பவள்தானே.", "en": "Which things are an allegory: for these are the two covenants; the one from the mount Sinai, which gendereth to bondage, which is Agar."}, {"verse": 25, "start": 226.8, "end": 237.02, "ta": "ஆகார் என்பது அரபிதேசத்திலுள்ள சீனாய்மலை; அந்த ஆகார் இப்பொழுதிருக்கிற எருசலேமுக்குச் சரி; இவள் தன் பிள்ளைகளோடேகூட அடிமைப்பட்டிருக்கிறாளே.", "en": "For this Agar is mount Sinai in Arabia, and answereth to Jerusalem which now is, and is in bondage with her children."}, {"verse": 26, "start": 237.02, "end": 241.97, "ta": "மேலான எருசலேமோ சுயாதீனமுள்ளவள், அவளே நம்மெல்லாருக்கும் தாயானவள்.", "en": "But Jerusalem which is above is free, which is the mother of us all."}, {"verse": 27, "start": 241.97, "end": 255.45, "ta": "அந்தப்படி பிள்ளைபெறாத மலடியே, மகிழ்ந்திரு; கர்ப்பவேதனைப்படாதவளே, களிப்பாய் எழும்பி ஆர்ப்பரி; புருஷனுள்ளவளைப் பார்க்கிலும் அநாத ஸ்திரீக்கே அதிக பிள்ளைகளுண்டு என்று எழுதியிருக்கிறது.", "en": "For it is written, Rejoice, thou barren that bearest not; break forth and cry, thou that travailest not: for the desolate hath many more children than she which hath an husband."}, {"verse": 28, "start": 255.45, "end": 260.4, "ta": "சகோதரரே நாம் ஈசாக்கைப்போல வாக்குத்தத்தத்துப் பிள்ளைகளாயிருக்கிறோம்.", "en": "Now we, brethren, as Isaac was, are the children of promise."}, {"verse": 29, "start": 260.4, "end": 268.61, "ta": "ஆகிலும் மாம்சத்தின்படி பிறந்தவன் ஆவியின்படி பிறந்தவனை அப்பொழுது துன்பப்படுத்தினது போல, இப்பொழுதும் நடந்துவருகிறது.", "en": "But as then he that was born after the flesh persecuted him that was born after the Spirit, even so it is now."}, {"verse": 30, "start": 268.61, "end": 281.96, "ta": "அதைக்குறித்து வேதம் என்னசொல்லுகிறது: அடிமையானவளின் மகன் சுயாதீனமுள்ளவளுடைய குமாரனோடே சுதந்தரவாளியாயிருப்பதில்லை; ஆகையால் அடிமையானவளையும், அவளுடைய மகனையும் புறம்பே தள்ளு என்று சொல்லுகிறது.", "en": "Nevertheless what saith the scripture? Cast out the bondwoman and her son: for the son of the bondwoman shall not be heir with the son of the freewoman."}, {"verse": 31, "start": 281.96, "end": 290.1, "ta": "இப்படியிருக்க, சகோதரரே, நாம் அடிமையானவளுக்குப் பிள்ளைகளாயிராமல், சுயாதீனமுள்ளவளுக்கே பிள்ளைகளாயிருக்கிறோம்.", "en": "So then, brethren, we are not children of the bondwoman, but of the free."}]}, "5": {"chapter": 5, "duration": 233.1, "audio_url": "audio_nt/B09_05.mp3", "total_verses": 26, "verses": [{"verse": 1, "start": 3.8, "end": 13.7, "ta": "ஆனபடியினாலே, நீங்கள் மறுபடியும் அடிமைத்தனத்தின் நுகத்துக்குட்படாமல், கிறிஸ்து நமக்கு உண்டாக்கின சுயாதீன நிலைமையிலே நிலைகொண்டிருங்கள்.", "en": "Stand fast therefore in the liberty wherewith Christ hath made us free, and be not entangled again with the yoke of bondage."}, {"verse": 2, "start": 13.7, "end": 23.47, "ta": "இதோ, நீங்கள் விருத்தசேதனம்பண்ணிக்கொண்டால் கிறிஸ்துவினால் உங்களுக்கு ஒரு பிரயோஜனமுமிராது என்று பவுலாகிய நான் உங்களுக்குச் சொல்லுகிறேன்.", "en": "Behold, I Paul say unto you, that if ye be circumcised, Christ shall profit you nothing."}, {"verse": 3, "start": 23.47, "end": 36.11, "ta": "மேலும், விருத்தசேதனம்பண்ணிக்கொள்ளுகிற எந்த மனுஷனும் நியாயப்பிரமாணம் முழுவதையும் நிறைவேற்றக் கடனாளியாயிருக்கிறான் என்று மறுபடியும் அப்படிப்பட்டவனுக்குச் சாட்சியாகச் சொல்லுகிறேன்.", "en": "For I testify again to every man that is circumcised, that he is a debtor to do the whole law."}, {"verse": 4, "start": 36.11, "end": 44.74, "ta": "நியாயப்பிரமாணத்தினால் நீதிமான்களாக விரும்புகிற நீங்கள் யாவரும் கிறிஸ்துவைவிட்டுப் பிரிந்து கிருபையினின்று விழுந்தீர்கள்.", "en": "Christ is become of no effect unto you, whosoever of you are justified by the law; ye are fallen from grace."}, {"verse": 5, "start": 44.74, "end": 51.23, "ta": "நாங்களோ நீதிகிடைக்குமென்று ஆவியைக்கொண்டு விசுவாசத்தினால் நம்பிக்கையோடே காத்திருக்கிறோம்.", "en": "For we through the Spirit wait for the hope of righteousness by faith."}, {"verse": 6, "start": 51.23, "end": 60.53, "ta": "கிறிஸ்து இயேசுவினிடத்தில் விருத்தசேதனமும் விருத்தசேதனமில்லாமையும் ஒன்றுக்கும் உதவாது, அன்பினால் கிரியைசெய்கிற விசுவாசமே உதவும்.", "en": "For in Jesus Christ neither circumcision availeth any thing, nor uncircumcision; but faith which worketh by love."}, {"verse": 7, "start": 60.53, "end": 67.76, "ta": "நீங்கள் நன்றாய் ஓடினீர்களே; சத்தியத்திற்குக் கீழ்ப்படியாமற்போக உங்களுக்குத் தடைசெய்தவன் யார்?", "en": "Ye did run well; who did hinder you that ye should not obey the truth?"}, {"verse": 8, "start": 67.76, "end": 71.24, "ta": "இந்தப் போதனை உங்களை அழைத்தவரால் உண்டானதல்ல.", "en": "This persuasion cometh not of him that calleth you."}, {"verse": 9, "start": 71.24, "end": 75.92, "ta": "புளிப்புள்ள கொஞ்சமாவானது பிசைந்த மாவனைத்தையும் உப்பப்பண்ணும்.", "en": "A little leaven leaveneth the whole lump."}, {"verse": 10, "start": 75.92, "end": 89.43, "ta": "நீங்கள் வேறுவிதமாய்ச் சிந்திக்கமாட்டீர்களென்று நான் கர்த்தருக்குள் உங்களைக்குறித்து நம்பிக்கையாயிருக்கிறேன்; உங்களைக் கலக்குகிறவன் எப்படிப்பட்டவனாயிருந்தாலும் தனக்கேற்ற ஆக்கினையை அடைவான்.", "en": "I have confidence in you through the Lord, that ye will be none otherwise minded: but he that troubleth you shall bear his judgment, whosoever he be."}, {"verse": 11, "start": 89.43, "end": 102.15, "ta": "சகோதரரே, இதுவரைக்கும் நான் விருத்தசேதனத்தைப் பிரசங்கிக்கிறவனாயிருந்தால், இதுவரைக்கும் என்னத்திற்குத் துன்பப்படுகிறேன்? அப்படியானால் சிலுவையைப்பற்றி வரும் இடறல் ஒழிந்திருக்குமே", "en": "And I, brethren, if I yet preach circumcision, why do I yet suffer persecution? then is the offence of the cross ceased."}, {"verse": 12, "start": 102.15, "end": 106.63, "ta": "உங்களைக் கலக்குகிறவர்கள் தறிப்புண்டுபோனால் நலமாயிருக்கும்.", "en": "I would they were even cut off which trouble you."}, {"verse": 13, "start": 106.63, "end": 118.27, "ta": "சகோதரரே, நீங்கள் சுயாதீனத்திற்கு அழைக்கப்பட்டீர்கள், இந்தச் சுயாதீனத்தை நீங்கள் மாம்சத்திற்கேதுவாக அநுசரியாமல், அன்பினாலே ஒருவருக்கொருவர் ஊழியஞ்செய்யுங்கள்.", "en": "For, brethren, ye have been called unto liberty; only use not liberty for an occasion to the flesh, but by love serve one another."}, {"verse": 14, "start": 118.27, "end": 127.84, "ta": "உன்னிடத்தில் நீ அன்புகூருவதுபோலப் பிறனிடத்திலும் அன்புகூருவாயாக, என்கிற இந்த ஒரே வார்த்தையிலே நியாயப்பிரமாணம் முழுவதும் நிறைவேறும்.", "en": "For all the law is fulfilled in one word, even in this; Thou shalt love thy neighbour as thyself."}, {"verse": 15, "start": 127.84, "end": 137.47, "ta": "நீங்கள் ஒருவரையொருவர் கடித்துப் பட்சித்தீர்களானால் அழிவீர்கள். அப்படி ஒருவராலொருவர் அழிக்கப்படாதபடிக்கு எச்சரிக்கையாயிருங்கள்.", "en": "But if ye bite and devour one another, take heed that ye be not consumed one of another."}, {"verse": 16, "start": 137.47, "end": 146.43, "ta": "பின்னும் நான் சொல்லுகிறதென்னவென்றால், ஆவிக்கேற்றபடி நடந்துகொள்ளுங்கள், அப்பொழுது மாம்ச இச்சையை நிறைவேற்றாதிருப்பீர்கள்.", "en": "This I say then, Walk in the Spirit, and ye shall not fulfil the lust of the flesh."}, {"verse": 17, "start": 146.43, "end": 159.28, "ta": "மாம்சம் ஆவிக்கு விரோதமாகவும், ஆவி மாம்சத்துக்கு விரோதமாகவும் இச்சிக்கிறது; நீங்கள் செய்யவேண்டுமென்றிருக்கிறவைகளைச் செய்யாதபடிக்கு, இவைகள் ஒன்றுக்கொன்று விரோதமாயிருக்கிறது.", "en": "For the flesh lusteth against the Spirit, and the Spirit against the flesh: and these are contrary the one to the other: so that ye cannot do the things that ye would."}, {"verse": 18, "start": 159.28, "end": 165.7, "ta": "ஆவியினால் நடத்தப்படுவீர்களானால், நீங்கள் நியாயப்பிரமாணத்திற்குக் கீழ்ப்பட்டவர்களல்ல.", "en": "But if ye be led of the Spirit, ye are not under the law."}, {"verse": 19, "start": 165.7, "end": 173.33, "ta": "மாம்சத்தின் கிரியைகள் வெளியரங்கமாயிருக்கின்றன, அவையாவன: விபசாரம், வேசித்தனம், அசுத்தம், காமவிகாரம்,", "en": "Now the works of the flesh are manifest, which are these ; Adultery, fornication, uncleanness, lasciviousness,"}, {"verse": 20, "start": 173.33, "end": 182.9, "ta": "விக்கிரகாராதனை, பில்லிசூனியம், பகைகள், விரோதங்கள், வைராக்கியங்கள், கோபங்கள், சண்டைகள், பிரிவினைகள், மார்க்கபேதங்கள்,", "en": "Idolatry, witchcraft, hatred, variance, emulations, wrath, strife, seditions, heresies,"}, {"verse": 21, "start": 182.9, "end": 197.55, "ta": "பொறாமைகள், கொலைகள், வெறிகள், களியாட்டுகள் முதலானவைகளே; இப்படிப்பட்டவைகளைச் செய்கிறவர்கள் தேவனுடைய ராஜ்யத்தைச் சுதந்தரிப்பதில்லையென்று முன்னே நான் சொன்னதுபோல இப்பொழுதும் உங்களுக்குச் சொல்லுகிறேன்.", "en": "Envyings, murders, drunkenness, revellings, and such like: of the which I tell you before, as I have also told you in time past, that they which do such things shall not inherit the kingdom of God."}, {"verse": 22, "start": 197.55, "end": 204.57, "ta": "ஆவியின் கனியோ, அன்பு, சந்தோஷம், சமாதானம், நீடியபொறுமை, தயவு, நற்குணம், விசுவாசம்,", "en": "But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith,"}, {"verse": 23, "start": 204.57, "end": 210.79, "ta": "சாந்தம், இச்சையடக்கம்; இப்படிப்பட்டவைகளுக்கு விரோதமான பிரமாணம் ஒன்றுமில்லை.", "en": "Meekness, temperance: against such there is no law."}, {"verse": 24, "start": 210.79, "end": 217.95, "ta": "கிறிஸ்துவினுடையவர்கள் தங்கள் மாம்சத்தையும் அதின் ஆசை இச்சைகளையும் சிலுவையில் அறைந்திருக்கிறார்கள்.", "en": "And they that are Christ’s have crucified the flesh with the affections and lusts."}, {"verse": 25, "start": 217.95, "end": 223.04, "ta": "நாம் ஆவியினாலே பிழைத்திருந்தால், ஆவிக்கேற்றபடி நடக்கவும் கடவோம்.", "en": "If we live in the Spirit, let us also walk in the Spirit."}, {"verse": 26, "start": 223.04, "end": 231.6, "ta": "வீண் புகழ்ச்சியை விரும்பாமலும், ஒருவரையொருவர் கோபமூட்டாமலும், ஒருவர்மேல் ஒருவர் பொறாமைகொள்ளாமலும் இருக்கக்கடவோம்.", "en": "Let us not be desirous of vain glory, provoking one another, envying one another."}]}, "6": {"chapter": 6, "duration": 175.35, "audio_url": "audio_nt/B09_06.mp3", "total_verses": 18, "verses": [{"verse": 1, "start": 3.8, "end": 18.41, "ta": "சகோதரரே, ஒருவன் யாதொரு குற்றத்தில் அகப்பட்டால், ஆவிக்குரியவர்களாகிய நீங்கள் சாந்தமுள்ள ஆவியோடே அப்படிப்பட்டவனைச் சீர்பொருந்தப்பண்ணுங்கள்; நீயும் சோதிக்கப்படாதபடிக்கு உன்னைக்குறித்து எச்சரிக்கையாயிரு.", "en": "Brethren, if a man be overtaken in a fault, ye which are spiritual, restore such an one in the spirit of meekness; considering thyself, lest thou also be tempted."}, {"verse": 2, "start": 18.41, "end": 24.72, "ta": "ஒருவர் பாரத்தை ஒருவர் சுமந்து, அப்படியே கிறிஸ்துவினுடைய பிரமாணத்தை நிறைவேற்றுங்கள்.", "en": "Bear ye one another’s burdens, and so fulfil the law of Christ."}, {"verse": 3, "start": 24.72, "end": 32.56, "ta": "ஒருவன், தான் ஒன்றுமில்லாதிருந்தும், தன்னை ஒரு பொருட்டென்று எண்ணினால், தன்னைத்தானே வஞ்சிக்கிறவனாவான்.", "en": "For if a man think himself to be something, when he is nothing, he deceiveth himself."}, {"verse": 4, "start": 32.56, "end": 43.79, "ta": "அவனவன் தன்தன் சுயகிரியையைச் சோதித்துப்பார்க்கக்கடவன்; அப்பொழுது மற்றவனைப் பார்க்கும்போதல்ல, தன்னையே பார்க்கும்போது மேன்மைபாராட்ட அவனுக்கு இடமுண்டாகும்.", "en": "But let every man prove his own work, and then shall he have rejoicing in himself alone, and not in another."}, {"verse": 5, "start": 43.79, "end": 46.64, "ta": "அவனவன் தன்தன் பாரத்தைச் சுமப்பானே.", "en": "For every man shall bear his own burden."}, {"verse": 6, "start": 46.64, "end": 54.48, "ta": "மேலும், திருவசனத்தில் உபதேசிக்கப்படுகிறவன் உபதேசிக்கிறவனுக்குச் சகல நன்மைகளிலும் பகிர்ந்து கொடுக்கக்கடவன்.", "en": "Let him that is taught in the word communicate unto him that teacheth in all good things."}, {"verse": 7, "start": 54.48, "end": 62.06, "ta": "மோசம்போகாதிருங்கள், தேவன் தம்மைப் பரியாசம்பண்ணவொட்டார்; மனுஷன் எதை விதைக்கிறானோ அதையே அறுப்பான்.", "en": "Be not deceived; God is not mocked: for whatsoever a man soweth, that shall he also reap."}, {"verse": 8, "start": 62.06, "end": 71.29, "ta": "தன் மாம்சத்திற்கென்று விதைக்கிறவன் மாம்சத்தினால் அழிவை அறுப்பான்; ஆவிக்கென்று விதைக்கிறவன் ஆவியினாலே நித்தியஜீவனை அறுப்பான்.", "en": "For he that soweth to his flesh shall of the flesh reap corruption; but he that soweth to the Spirit shall of the Spirit reap life everlasting."}, {"verse": 9, "start": 71.29, "end": 78.73, "ta": "நன்மைசெய்கிறதில் சோர்ந்துபோகாமல் இருப்போமாக; நாம் தளர்ந்துபோகாதிருந்தால் ஏற்றகாலத்தில் அறுப்போம்.", "en": "And let us not be weary in well doing: for in due season we shall reap, if we faint not."}, {"verse": 10, "start": 78.73, "end": 88.09, "ta": "ஆகையால் நமக்குக் கிடைக்கும் சமயத்திற்குத்தக்கதாக, யாவருக்கும், விசேஷமாக விசுவாச குடும்பத்தார்களுக்கும், நன்மைசெய்யக்கடவோம்.", "en": "As we have therefore opportunity, let us do good unto all men , especially unto them who are of the household of faith."}, {"verse": 11, "start": 88.09, "end": 91.95, "ta": "என் கையெழுத்தாய் எவ்வளவு எழுதினேனென்று பாருங்கள்.", "en": "Ye see how large a letter I have written unto you with mine own hand."}, {"verse": 12, "start": 91.95, "end": 105.43, "ta": "மாம்சத்தின்படி நல்வேஷமாய்க் காணப்பட விரும்புகிறவர்கள் எவர்களோ, அவர்கள் தாங்கள் கிறிஸ்துவினுடைய சிலுவையினிமித்தம் துன்பப்படாதபடிக்கே உங்களை விருத்தசேதனம் பண்ணிக்கொள்ளக் கட்டாயம்பண்ணுகிறார்கள்.", "en": "As many as desire to make a fair shew in the flesh, they constrain you to be circumcised; only lest they should suffer persecution for the cross of Christ."}, {"verse": 13, "start": 105.43, "end": 121.77, "ta": "விருத்தசேதனம் அடைந்திருக்கிற அவர்களும் நியாயப்பிரமாணத்தைக் கைக்கொள்ளாமலிருக்கிறார்கள்; அப்படியிருந்தும், அவர்கள் உங்கள் மாம்சத்தைக்குறித்து மேன்மைபாராட்டும்படிக்கு நீங்கள் விருத்தசேதனம்பண்ணிக்கொள்ளவேண்டுமென்று விரும்புகிறார்கள்.", "en": "For neither they themselves who are circumcised keep the law; but desire to have you circumcised, that they may glory in your flesh."}, {"verse": 14, "start": 121.77, "end": 137.58, "ta": "நானோ நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவின் சிலுவையைக் குறித்தேயல்லாமல் வேறொன்றையுங் குறித்து மேன்மைபாராட்டாதிருப்பேனாக; அவரால் உலகம் எனக்குச் சிலுவையிலறையுண்டிருக்கிறது, நானும் உலகத்திற்குச் சிலுவையிலறையுண்டிருக்கிறேன்.", "en": "But God forbid that I should glory, save in the cross of our Lord Jesus Christ, by whom the world is crucified unto me, and I unto the world."}, {"verse": 15, "start": 137.58, "end": 146.28, "ta": "கிறிஸ்து இயேசுவுக்குள் விருத்தசேதனமும் ஒன்றுமில்லை, விருத்தசேதனமில்லாமையும் ஒன்றுமில்லை; புது சிருஷ்டியே காரியம்.", "en": "For in Christ Jesus neither circumcision availeth any thing, nor uncircumcision, but a new creature."}, {"verse": 16, "start": 146.28, "end": 156.05, "ta": "இந்தப் பிரமாணத்தின்படி நடந்துவருகிறவர்கள் எவர்களோ, அவர்களுக்கும், தேவனுடைய இஸ்ரவேலருக்கும், சமாதானமும் இரக்கமும் உண்டாயிருப்பதாக.", "en": "And as many as walk according to this rule, peace be on them, and mercy, and upon the Israel of God."}, {"verse": 17, "start": 156.05, "end": 166.41, "ta": "இனிமேல் ஒருவனும் எனக்கு வருத்தம் உண்டாக்காதிருப்பானாக; கர்த்தராகிய இயேசுவினுடைய அச்சடையாளங்களை நான் என் சரீரத்திலே தரித்துக்கொண்டிருக்கிறேன்.", "en": "From henceforth let no man trouble me: for I bear in my body the marks of the Lord Jesus."}, {"verse": 18, "start": 166.41, "end": 173.85, "ta": "சகோதரரே, நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவின் கிருபை உங்கள் ஆவியுடனேகூட இருப்பதாக. ஆமென்.", "en": "Brethren, the grace of our Lord Jesus Christ be with your spirit. Amen."}]}}});
} else {
  window.BIBLE_CACHE = window.BIBLE_CACHE || {};
  window.BIBLE_CACHE['48'] = {"id": 48, "testament": "NT", "code": "GAL", "name_en": "Galatians", "name_ta": "கலாத்தியர்", "category": "Pauline Epistles", "category_ta": "பவுலின் நிருபங்கள்", "total_chapters": 6, "chapters": {"1": {"chapter": 1, "duration": 221.97, "audio_url": "audio_nt/B09_01.mp3", "total_verses": 24, "verses": [{"verse": 1, "start": 4.8, "end": 15.33, "ta": "மனுஷராலுமல்ல, மனுஷன் மூலமாயுமல்ல, இயேசுகிறிஸ்துவினாலும், அவரை மரித்தோரிலிருந்தெழுப்பின பிதாவாகிய தேவனாலும், அப்போஸ்தலனாயிருக்கிற பவுலாகிய நானும்,", "en": "Paul, an apostle, (not of men, neither by man, but by Jesus Christ, and God the Father, who raised him from the dead;)"}, {"verse": 2, "start": 15.33, "end": 21.13, "ta": "என்னுடனேகூட இருக்கிற சகோதரரெல்லாரும், கலாத்தியா நாட்டிலுள்ள சபைகளுக்கு எழுதுகிறதாவது:", "en": "And all the brethren which are with me, unto the churches of Galatia:"}, {"verse": 3, "start": 21.13, "end": 28.89, "ta": "பிதாவாகிய தேவனாலும், நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவினாலும் உங்களுக்குக் கிருபையும் சமாதானமும் உண்டாவதாக;", "en": "Grace be to you and peace from God the Father, and from our Lord Jesus Christ,"}, {"verse": 4, "start": 28.89, "end": 40.48, "ta": "அவர் நம்மை இப்பொழுதிருக்கிற பொல்லாத பிரபஞ்சத்தினின்று விடுவிக்கும்படி நம்முடைய பிதாவாகிய தேவனுடைய சித்தத்தின்படியே நம்முடைய பாவங்களுக்காகத் தம்மைத்தாமே ஒப்புக்கொடுத்தார்;", "en": "Who gave himself for our sins, that he might deliver us from this present evil world, according to the will of God and our Father:"}, {"verse": 5, "start": 40.48, "end": 45.42, "ta": "அவருக்கு என்றென்றைக்குமுள்ள சதாகாலங்களிலும் மகிமை உண்டாவதாக ஆமென்.", "en": "To whom be glory for ever and ever. Amen."}, {"verse": 6, "start": 45.42, "end": 55.95, "ta": "உங்களைக் கிறிஸ்துவின் கிருபையினாலே அழைத்தவரை நீங்கள் இவ்வளவு சீக்கிரமாய் விட்டு, வேறொரு சுவிசேஷத்திற்குத் திரும்புகிறதைப்பற்றி நான் ஆச்சரியப்படுகிறேன்;", "en": "I marvel that ye are so soon removed from him that called you into the grace of Christ unto another gospel:"}, {"verse": 7, "start": 55.95, "end": 65.37, "ta": "வேறொரு சுவிசேஷம் இல்லையே; சிலர் உங்களைக் கலகப்படுத்தி, கிறிஸ்துவிடைய சுவிசேஷத்தைப் புரட்ட மனதாயிருக்கிறார்களேயல்லாமல் வேறல்ல.", "en": "Which is not another; but there be some that trouble you, and would pervert the gospel of Christ."}, {"verse": 8, "start": 65.37, "end": 78.99, "ta": "நாங்கள் உங்களுக்குப் பிரசங்கித்த சுவிசேஷத்தையல்லாமல், நாங்களாவது, வானத்திலிருந்து வருகிற ஒரு தூதனாவது, வேறொரு சுவிசேஷத்தை உங்களுக்குப் பிரசங்கித்தால், அவன் சபிக்கப்பட்டவனாயிருக்கக்கடவன்.", "en": "But though we, or an angel from heaven, preach any other gospel unto you than that which we have preached unto you, let him be accursed."}, {"verse": 9, "start": 78.99, "end": 91.24, "ta": "முன் சொன்னதுபோல மறுபடியும் சொல்லுகிறேன்; நீங்கள் ஏற்றுக்கொண்ட சுவிசேஷத்தையல்லாமல் வேறொரு சுவிசேஷத்தை ஒருவன் உங்களுக்குப் பிரசங்கித்தால் அவன் சபிக்கப்பட்டவனாயிருக்கக்கடவன்.", "en": "As we said before, so say I now again, If any man preach any other gospel unto you than that ye have received, let him be accursed."}, {"verse": 10, "start": 91.24, "end": 105.66, "ta": "இப்பொழுது நான் மனுஷரையா, தேவனையா, யாரை நாடிப் போதிக்கிறேன்? மனுஷரையா பிரியப்படுத்தப் பார்க்கிறேன்? நான் இன்னும் மனுஷரைப் பிரியப்படுத்துகிறவனாயிருந்தால் நான் கிறிஸ்துவின் ஊழியக்காரனல்லவே.", "en": "For do I now persuade men, or God? or do I seek to please men? for if I yet pleased men, I should not be the servant of Christ."}, {"verse": 11, "start": 105.66, "end": 114.35, "ta": "மேலும், சகோதரரே, என்னால் பிரசங்கிக்கப்பட்ட சுவிசேஷம் மனுஷருடைய யோசனையின்படியானதல்லவென்று உங்களுக்குத் தெரிவிக்கிறேன்.", "en": "But I certify you, brethren, that the gospel which was preached of me is not after man."}, {"verse": 12, "start": 114.35, "end": 122.25, "ta": "நான் அதை ஒரு மனுஷனால் பெற்றதுமில்லை, மனுஷனால் கற்றதுமில்லை, இயேசுகிறிஸ்துவே அதை எனக்கு வெளிப்படுத்தினார்.", "en": "For I neither received it of man, neither was I taught it , but by the revelation of Jesus Christ."}, {"verse": 13, "start": 122.25, "end": 132.85, "ta": "நான் யூதமார்க்கத்திலிருந்தபோது என்னுடைய நடக்கையைக்குறித்துக் கேள்விப்பட்டிருப்பீர்கள்; தேவனுடைய சபையை நான் மிகவும் துன்பப்படுத்தி, அதைப் பாழாக்கி;", "en": "For ye have heard of my conversation in time past in the Jews’ religion, how that beyond measure I persecuted the church of God, and wasted it:"}, {"verse": 14, "start": 132.85, "end": 144.24, "ta": "என் ஜனத்தாரில் என் வயதுள்ள அநேகரைப்பார்க்கிலும் யூதமார்க்கத்திலே தேறினவனாய், என் பிதாக்களுடைய பாரம்பரிய நியாயங்களுக்காக மிகவும் பக்திவைராக்கியமுள்ளவனாயிருந்தேன்.", "en": "And profited in the Jews’ religion above many my equals in mine own nation, being more exceedingly zealous of the traditions of my fathers."}, {"verse": 15, "start": 144.24, "end": 152.73, "ta": "அப்படியிருந்தும், நான் என் தாயின் வயிற்றிலிருந்தது முதல், என்னைப் பிரித்தெடுத்து, தம்முடைய கிருபையினால் அழைத்த தேவன்,", "en": "But when it pleased God, who separated me from my mother’s womb, and called me by his grace,"}, {"verse": 16, "start": 152.73, "end": 165.17, "ta": "தம்முடைய குமாரனை நான் புறஜாதிகளிடத்தில் சுவிசேஷமாய் அறிவிக்கும்பொருட்டாக, அவரை எனக்குள் வெளிப்படுத்தப் பிரியமாயிருந்தபோது, உடனே நான் மாம்சத்தோடும் இரத்தத்தோடும் யோசனைபண்ணாமலும்;", "en": "To reveal his Son in me, that I might preach him among the heathen; immediately I conferred not with flesh and blood:"}, {"verse": 17, "start": 165.17, "end": 175.9, "ta": "எனக்கு முன்னே அப்போஸ்தலரானவர்களிடத்திலே எருசலேமுக்குப்போகாமலும்; அரபிதேசத்திற்குப் புறப்பட்டுப்போய், மறுபடியும் தமஸ்கு ஊருக்குத் திரும்பிவந்தேன்.", "en": "Neither went I up to Jerusalem to them which were apostles before me; but I went into Arabia, and returned again unto Damascus."}, {"verse": 18, "start": 175.9, "end": 185.12, "ta": "மூன்று வருஷம் சென்ற பின்பு, பேதுருவைக் கண்டுகொள்ளும்படி நான் எருசலேமுக்குப் போய், அவனிடத்தில் பதினைந்து நாள் தங்கியிருந்தேன்.", "en": "Then after three years I went up to Jerusalem to see Peter, and abode with him fifteen days."}, {"verse": 19, "start": 185.12, "end": 191.37, "ta": "கர்த்தருடைய சகோதரனாகிய யாக்கோபைத் தவிர, அப்போஸ்தலரில் வேறொருவரையும் நான் காணவில்லை.", "en": "But other of the apostles saw I none, save James the Lord’s brother."}, {"verse": 20, "start": 191.37, "end": 197.89, "ta": "நான் உங்களுக்கு எழுதுகிற இவைகள் பொய்யல்லவென்று தேவனுக்குமுன்பாக நிச்சயமாய்ச் சொல்லுகிறேன்.", "en": "Now the things which I write unto you, behold, before God, I lie not."}, {"verse": 21, "start": 197.89, "end": 202.17, "ta": "பின்பு, சீரியா சிலிசியா நாடுகளின் புறங்களில் வந்தேன்.", "en": "Afterwards I came into the regions of Syria and Cilicia;"}, {"verse": 22, "start": 202.17, "end": 207.83, "ta": "மேலும் யூதேயாதேசத்திலே கிறிஸ்துவுக்குள்ளான சபைகளுக்கு முகமறியாதவனாயிருந்தேன்.", "en": "And was unknown by face unto the churches of Judaea which were in Christ:"}, {"verse": 23, "start": 207.83, "end": 217.18, "ta": "முன்னே நம்மைத் துன்பப்படுத்தினவனே, தான் அழிக்கத்தேடின விசுவாசத்தை இப்பொழுது பிரசங்கிக்கிறானென்பதை மாத்திரம் அவர்கள் கேள்விப்பட்டிருந்து,", "en": "But they had heard only, That he which persecuted us in times past now preacheth the faith which once he destroyed."}, {"verse": 24, "start": 217.18, "end": 220.47, "ta": "என்னைப்பற்றி தேவனை மகிமைப்படுத்தினார்கள்.", "en": "And they glorified God in me."}]}, "2": {"chapter": 2, "duration": 254.37, "audio_url": "audio_nt/B09_02.mp3", "total_verses": 21, "verses": [{"verse": 1, "start": 3.8, "end": 11.59, "ta": "பதினாலு வருஷம் சென்றபின்பு, நான் தீத்துவைக் கூட்டிக்கொண்டு பர்னபாவுடனேகூட மறுபடியும் எருசலேமுக்குப் போனேன்.", "en": "Then fourteen years after I went up again to Jerusalem with Barnabas, and took Titus with me also."}, {"verse": 2, "start": 11.59, "end": 27.7, "ta": "நான் தேவ அறிவிப்பினாலே போய், புறஜாதிகளிடத்தில் நான் பிரசங்கிக்கிற சுவிசேஷத்தை அவர்களுக்கு விவரித்துக் காண்பித்தேன்; ஆயினும் நான் ஓடுகிறதும், ஓடினதும் வீணாகாதபடிக்கு எண்ணிக்கையுள்ளவர்களுக்கே தனிமையாய் விவரித்துக் காண்பித்தேன்.", "en": "And I went up by revelation, and communicated unto them that gospel which I preach among the Gentiles, but privately to them which were of reputation, lest by any means I should run, or had run, in vain."}, {"verse": 3, "start": 27.7, "end": 35.82, "ta": "ஆனாலும் என்னுடனேகூட இருந்த தீத்து கிரேக்கனாயிருந்தும் விருத்தசேதனம்பண்ணிக்கொள்ளும்படிக்குக் கட்டாயம்பண்ணப்படவில்லை.", "en": "But neither Titus, who was with me, being a Greek, was compelled to be circumcised:"}, {"verse": 4, "start": 35.82, "end": 48.0, "ta": "கிறிஸ்து இயேசுவுக்குள் நமக்கு உண்டான சுயாதீனத்தை உளவுபார்த்து நம்மை நியாயப்பிரமாரணத்திற்கு அடிமைகளாக்கும்பொருட்டாகப் பக்கவழியாய் நுழைந்த கள்ளச் சகோதரர் நிமித்தம் அப்படியாயிற்று.", "en": "And that because of false brethren unawares brought in, who came in privily to spy out our liberty which we have in Christ Jesus, that they might bring us into bondage:"}, {"verse": 5, "start": 48.0, "end": 56.97, "ta": "சுவிசேஷத்தின் சத்தியம் உங்களிடத்திலே நிலைத்திருக்கும்படி, நாங்கள் ஒரு நாழிகையாகிலும் அவர்களுக்குக் கீழ்ப்படிந்து இணங்கவில்லை.", "en": "To whom we gave place by subjection, no, not for an hour; that the truth of the gospel might continue with you."}, {"verse": 6, "start": 56.97, "end": 69.6, "ta": "அல்லாமலும் எண்ணிக்கையுள்ளவர்களாயிருந்தவர்கள் எனக்கு ஒன்றும் போதிக்கவில்லை; அவர்கள் எப்படிப்பட்டவர்களாயிருந்தாலும் எனக்குக் கவலையில்லை, தேவன் மனுஷரிடத்தில் பட்சபாதமுள்ளவரல்லவே.", "en": "But of these who seemed to be somewhat, (whatsoever they were, it maketh no matter to me: God accepteth no man’s person:) for they who seemed to be somewhat in conference added nothing to me:"}, {"verse": 7, "start": 69.6, "end": 80.73, "ta": "அதுவுமல்லாமல், விருத்தசேதனமுள்ளவர்களுக்கு அப்போஸ்தலனாயிருக்கும்படி பேதுருவைப் பலப்படுத்தினவர் புறஜாதிகளுக்கு அப்போஸ்தலனாயிருக்கும்படி என்னையும் பலப்படுத்தினபடியால்,", "en": "But contrariwise, when they saw that the gospel of the uncircumcision was committed unto me, as the gospel of the circumcision was unto Peter;"}, {"verse": 8, "start": 80.73, "end": 94.29, "ta": "விருத்தசேதனமுள்ள அவர்களுக்குச் சுவிசேஷத்தைப் பிரசங்கிக்கும்படி பேதுருவுக்குக் கையளிக்கப்பட்டதுபோல, விருத்தசேதனம் இல்லாதவர்களுக்குப் பிரசங்கிக்கும்படி அது எனக்கும் கையளிக்கப்பட்டதென்று அவர்கள் கண்டு;", "en": "(For he that wrought effectually in Peter to the apostleship of the circumcision, the same was mighty in me toward the Gentiles:)"}, {"verse": 9, "start": 94.29, "end": 112.23, "ta": "எனக்கு அளிக்கப்பட்ட கிருபையை அறிந்தபோது, தூண்களாக எண்ணப்பட்ட யாக்கோபும், கேபாவும், யோவானும், தாங்கள் விருத்தசேதனமுள்ளவர்களுக்கும், நாங்கள் புறஜாதிகளுக்கும் பிரசங்கிக்கும்படி, அந்நியோந்நிய ஐக்கியத்திற்கு அடையாளமாக எனக்கும் பர்னபாவுக்கும் வலதுகை கொடுத்து,", "en": "And when James, Cephas, and John, who seemed to be pillars, perceived the grace that was given unto me, they gave to me and Barnabas the right hands of fellowship; that we should go unto the heathen, and they unto the circumcision."}, {"verse": 10, "start": 112.23, "end": 121.46, "ta": "தரித்திரரை நினைத்துக்கொள்ளும்படிக்குமாத்திரம் சொன்னார்கள்; அப்படிச் செய்யும்படி அதற்கு முன்னமே நானும் கருத்துள்ளவனாயிருந்தேன்.", "en": "Only they would that we should remember the poor; the same which I also was forward to do."}, {"verse": 11, "start": 121.46, "end": 129.71, "ta": "மேலும், பேதுரு அந்தியோகியாவுக்கு வந்தபோது, அவன்மேல் குற்றஞ்சுமந்ததினால், நான் முகமுகமாய் அவனோடே எதிர்த்தேன்.", "en": "But when Peter was come to Antioch, I withstood him to the face, because he was to be blamed."}, {"verse": 12, "start": 129.71, "end": 142.28, "ta": "எப்படியெனில், யாக்கோபினிடத்திலிருந்து சிலர் வருகிறதற்குமுன் அவன் புறஜாதியாருடனே சாப்பிட்டான்; அவர்கள் வந்தபோதோ, விருத்தசேதனமுள்ளவர்களுக்குப் பயந்து, விலகிப் பிரிந்தான்.", "en": "For before that certain came from James, he did eat with the Gentiles: but when they were come, he withdrew and separated himself, fearing them which were of the circumcision."}, {"verse": 13, "start": 142.28, "end": 149.22, "ta": "மற்ற யூதரும் அவனுடனேகூட மாயம்பண்ணினார்கள்; அவர்களுடைய மாயத்தினாலே பர்னபாவும் இழுப்புண்டான்.", "en": "And the other Jews dissembled likewise with him; insomuch that Barnabas also was carried away with their dissimulation."}, {"verse": 14, "start": 149.22, "end": 170.24, "ta": "இப்படி அவர்கள் சுவிசேஷத்தின் சத்தியத்திற்கேற்றபடி சரியாய் நடவாததை நான் கண்டபோது, எல்லாருக்கும் முன்பாக நான் பேதுருவை நோக்கிச்சொன்னது என்னவென்றால்: யூதனாயிருக்கிற நீர் யூதர் முறைமையாக நடவாமல், புறஜாதியார் முறைமையாக நடந்துகொண்டிருக்க, புறஜாதியாரை யூதர்முறைமையாக நடக்கும்படி நீர் எப்படிக்கட்டாயம் பண்ணலாம்?", "en": "But when I saw that they walked not uprightly according to the truth of the gospel, I said unto Peter before them all, If thou, being a Jew, livest after the manner of Gentiles, and not as do the Jews, why compellest thou the Gentiles to live as do the Jews?"}, {"verse": 15, "start": 170.24, "end": 194.14, "ta": "புறஜாதியாரில் பிறந்த பாவிகளாயிராமல், சுபாவத்தின்படி யூதராயிருக்கிற நாமும் இயேசுகிறிஸ்துவைப்பற்றும் விசுவாசத்தினாலேயன்றி, நியாயப்பிரமாணத்தின் கிரியைகளினாலே மனுஷன் நீதிமானாக்கப்படுவதில்லையென்று அறிந்து, நியாயப்பிரமாணத்தின் கிரியைகளினாலல்ல, கிறிஸ்துவைப்பற்றும் விசுவாசத்தினாலே நீதிமான்களாக்கப்படும்படிக்குக் கிறிஸ்து இயேசுவின்மேல் விசுவாசிகளானோம்.", "en": "We who are Jews by nature, and not sinners of the Gentiles,"}, {"verse": 16, "start": 194.14, "end": 199.57, "ta": "நியாயப்பிரமாணத்தின் கிரியைகளினாலே எந்த மனுஷனும் நீதிமானாக்கப்படுவதில்லையே.", "en": "Knowing that a man is not justified by the works of the law, but by the faith of Jesus Christ, even we have believed in Jesus Christ, that we might be justified by the faith of Christ, and not by the works of the law: for by the works of the law shall no flesh be justified."}, {"verse": 17, "start": 199.57, "end": 209.07, "ta": "கிறிஸ்துவுக்குள் நீதிமான்களாக்கப்படும்படி நாடுகிற நாமும் பாவிகளாகக் காணப்படுவோமானால், கிறிஸ்து பாவத்திற்குக் காரணரோ? அல்லவே.", "en": "But if, while we seek to be justified by Christ, we ourselves also are found sinners, is therefore Christ the minister of sin? God forbid."}, {"verse": 18, "start": 209.07, "end": 215.94, "ta": "நான் இடித்துப்போட்டவைகளையே நான் மறுபடியும் கட்டினால், பிரமாணத்தை மீறுகிறவனென்று காணப்படுவேன்.", "en": "For if I build again the things which I destroyed, I make myself a transgressor."}, {"verse": 19, "start": 215.94, "end": 222.23, "ta": "தேவனுக்கென்று பிழைக்கும்படி நான் நியாயப்பிரமாணத்தினாலே நியாயப்பிரமாணத்திற்கு மரித்தேனே.", "en": "For I through the law am dead to the law, that I might live unto God."}, {"verse": 20, "start": 222.23, "end": 243.7, "ta": "கிறிஸ்துவுடனேகூடச் சிலுவையிலறையப்பட்டேன்; ஆயினும், பிழைத்திருக்கிறேன்; இனி நான் அல்ல, கிறிஸ்துவே எனக்குள் பிழைத்திருக்கிறார்; நான் இப்பொழுது மாம்சத்தில் பிழைத்திருக்கிறதோ, என்னில் அன்புகூர்ந்து எனக்காகத் தம்மைத்தாமே ஒப்புக்கொடுத்த தேவனுடைய குமாரனைப்பற்றும் விசுவாசத்தினாலே பிழைத்திருக்கிறேன்.", "en": "I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me."}, {"verse": 21, "start": 243.7, "end": 252.87, "ta": "நான் தேவனுடைய கிருபையை விருதாவாக்குகிறதில்லை; நீதியானது நியாயப்பிரமாணத்தினாலே வருமானால், கிறிஸ்து மரித்தது வீணாயிருக்குமே.", "en": "I do not frustrate the grace of God: for if righteousness come by the law, then Christ is dead in vain."}]}, "3": {"chapter": 3, "duration": 311.61, "audio_url": "audio_nt/B09_03.mp3", "total_verses": 29, "verses": [{"verse": 1, "start": 3.8, "end": 20.11, "ta": "புத்தியில்லாத கலாத்தியரே, நீங்கள் சத்தியத்திற்குக் கீழ்ப்படியாமற்போகத்தக்கதாக உங்களை மயக்கினவன் யார்? இயேசுகிறிஸ்து சிலுவையிலறையப்பட்டவராக உங்கள் கண்களுக்குமுன் பிரத்தியட்சமாய் உங்களுக்குள்ளே வெளிப்படுத்தப்பட்டிருந்தாரே.", "en": "O foolish Galatians, who hath bewitched you, that ye should not obey the truth, before whose eyes Jesus Christ hath been evidently set forth, crucified among you?"}, {"verse": 2, "start": 20.11, "end": 31.01, "ta": "ஒன்றைமாத்திரம் உங்களிடத்தில் அறியவிரும்புகிறேன்; நியாயப்பிரமாணத்தின் கிரியைகளினாலேயோ, விசுவாசக் கேள்வியினாலேயோ, எதினாலே ஆவியைப் பெற்றீர்கள்?", "en": "This only would I learn of you, Received ye the Spirit by the works of the law, or by the hearing of faith?"}, {"verse": 3, "start": 31.01, "end": 39.47, "ta": "ஆவியினாலே ஆரம்பம்பண்ணின நீங்கள் இப்பொழுது மாம்சத்தினாலே முடிவுபெறப்போகிறீர்களோ? நீங்கள் இத்தனை புத்தியீனரா?", "en": "Are ye so foolish? having begun in the Spirit, are ye now made perfect by the flesh?"}, {"verse": 4, "start": 39.47, "end": 45.02, "ta": "இத்தனை பாடுகளையும் வீணாய்ப் பட்டீர்களோ? அவைகள் வீணாய்ப்போயிற்றே.", "en": "Have ye suffered so many things in vain? if it be yet in vain."}, {"verse": 5, "start": 45.02, "end": 57.35, "ta": "அன்றியும் உங்களுக்கு ஆவியை அளித்து, உங்களுக்குள்ளே அற்புதங்களை நடப்பிக்கிறவர் அதை நியாயப்பிரமாணத்தின் கிரியைகளினாலேயோ, விசுவாசக் கேள்வியினாலேயோ, எதினாலே செய்கிறார்?", "en": "He therefore that ministereth to you the Spirit, and worketh miracles among you, doeth he it by the works of the law, or by the hearing of faith?"}, {"verse": 6, "start": 57.35, "end": 63.17, "ta": "அப்படியே ஆபிரகாம் தேவனை விசுவாசித்தான், அது அவனுக்கு நீதியாக எண்ணப்பட்டது.", "en": "Even as Abraham believed God, and it was accounted to him for righteousness."}, {"verse": 7, "start": 63.17, "end": 69.53, "ta": "ஆகையால் விசுவாசமார்க்கத்தார்கள் எவர்களோ அவர்களே ஆபிரகாமின் பிள்ளைகளென்று அறிவீர்களாக.", "en": "Know ye therefore that they which are of faith, the same are the children of Abraham."}, {"verse": 8, "start": 69.53, "end": 82.26, "ta": "மேலும் தேவன் விசுவாசத்தினாலே புறஜாதிகளை நீதிமான்களாக்குகிறாரென்று வேதம் முன்னாகக் கண்டு: உனக்குள் சகல ஜாதிகளும் ஆசீர்வதிக்கப்படும் என்று ஆபிரகாமுக்குச் சுவிசேஷமாய் முன்னறிவித்தது.", "en": "And the scripture, foreseeing that God would justify the heathen through faith, preached before the gospel unto Abraham, saying , In thee shall all nations be blessed."}, {"verse": 9, "start": 82.26, "end": 88.42, "ta": "அந்தப்படி விசுவாசமார்க்கத்தார் விசுவாசமுள்ள ஆபிரகாமுடனே ஆசீர்வதிக்கப்படுகிறார்கள்.", "en": "So then they which be of faith are blessed with faithful Abraham."}, {"verse": 10, "start": 88.42, "end": 104.12, "ta": "நியாயப்பிரமாணத்தின் கிரியைக்காரராகிய யாவரும் சாபத்திற்குட்பட்டிருக்கிறார்கள்; நியாயப்பிரமாண புஸ்தகத்தில் எழுதப்பட்டவைகளையெல்லாம் செய்யத்தக்கதாக அவைகளில் நிலைத்திராதவன் எவனோ அவன் சபிக்கப்பட்டவன் என்று எழுதியிருக்கிறதே.", "en": "For as many as are of the works of the law are under the curse: for it is written, Cursed is every one that continueth not in all things which are written in the book of the law to do them."}, {"verse": 11, "start": 104.12, "end": 116.44, "ta": "நியாயப்பிரமாணத்தினாலே ஒருவனும் தேவனிடத்தில் நீதிமானாகிறதில்லையென்பது வெளியரங்கமாயிருக்கிறது. ஏனெனில், விசுவாசத்தினாலே நீதிமான் பிழைப்பான் என்று எழுதியிருக்கிறதே.", "en": "But that no man is justified by the law in the sight of God, it is evident: for, The just shall live by faith."}, {"verse": 12, "start": 116.44, "end": 123.14, "ta": "நியாயப்பிரமாணமோ விசுவாசத்திற்குரியதல்ல; அவைகளைச் செய்கிற மனுஷனே அவைகளால் பிழைப்பான்.", "en": "And the law is not of faith: but, The man that doeth them shall live in them."}, {"verse": 13, "start": 123.14, "end": 135.19, "ta": "மரத்திலே தூக்கப்பட்ட எவனும் சபிக்கப்பட்டவன் என்று எழுதியிருக்கிறபடி, கிறிஸ்து நமக்காகச் சாபமாகி, நியாயப்பிரமாணத்தின் சாபத்திற்கு நம்மை நீங்லாக்கி மீட்டுக்கொண்டார்.", "en": "Christ hath redeemed us from the curse of the law, being made a curse for us: for it is written, Cursed is every one that hangeth on a tree:"}, {"verse": 14, "start": 135.19, "end": 148.46, "ta": "ஆபிரகாமுக்கு உண்டான ஆசீர்வாதம் கிறிஸ்து இயேசுவினால் புறஜாதிகளுக்கு வரும்படியாகவும், ஆவியைக்குறித்துச் சொல்லப்பட்ட வாக்குத்தத்தத்தை நாம் விசுவாசத்தினாலே பெறும்படியாகவும் இப்படியாயிற்று.", "en": "That the blessing of Abraham might come on the Gentiles through Jesus Christ; that we might receive the promise of the Spirit through faith."}, {"verse": 15, "start": 148.46, "end": 160.37, "ta": "சகோதரரே, மனுஷர் முறைமையின்படி சொல்லுகிறேன்; மனுஷர்களுக்குள்ளே உறுதிபண்ணப்பட்ட உடன்படிக்கையை ஒருவனும் தள்ளுகிறதுமில்லை, அதினோடே ஒன்றையும் கூட்டுகிறதுமில்லை.", "en": "Brethren, I speak after the manner of men; Though it be but a man’s covenant, yet if it be confirmed, no man disannulleth, or addeth thereto."}, {"verse": 16, "start": 160.37, "end": 175.47, "ta": "ஆபிரகாமுக்கும் அவனுடைய சந்ததிக்கும் வாக்குத்தத்தங்கள் பண்ணப்பட்டன; சந்ததிகளுக்கு என்று அநேகரைக்குறித்துச் சொல்லாமல், உன் சந்ததிக்கு என்று ஒருவனைக்குறித்துச் சொல்லியிருக்கிறார், அந்தச் சந்ததி கிறிஸ்துவே.", "en": "Now to Abraham and his seed were the promises made. He saith not, And to seeds, as of many; but as of one, And to thy seed, which is Christ."}, {"verse": 17, "start": 175.47, "end": 190.56, "ta": "ஆதலால் நான் சொல்லுகிறதென்னவெனில், கிறிஸ்துவை முன்னிட்டு தேவனால் முன் உறுதிபண்ணப்பட்ட உடன்படிக்கையை நானூற்றுமுப்பது வருஷத்திற்குப்பின்பு உண்டான நியாயப்பிரமாணமானது தள்ளி, வாக்குத்தத்தத்தை வியர்த்தமாக்கமாட்டாது.", "en": "And this I say, that the covenant, that was confirmed before of God in Christ, the law, which was four hundred and thirty years after, cannot disannul, that it should make the promise of none effect."}, {"verse": 18, "start": 190.56, "end": 202.21, "ta": "அன்றியும், சுதந்தரமானது நியாயப்பிரமாணத்தினாலே உண்டானால் அது வாக்குத்தத்தத்தினாலே உண்டாயிராது; தேவன் அதை ஆபிரகாமுக்கு வாக்குத்தத்தத்தினாலே அருளிச்செய்தாரே.", "en": "For if the inheritance be of the law, it is no more of promise: but God gave it to Abraham by promise."}, {"verse": 19, "start": 202.21, "end": 216.29, "ta": "அப்படியானால், நியாயப்பிரமாணத்தின் நோக்கமென்ன? வாக்குத்தத்தத்தைப்பெற்ற சந்ததி வருமளவும் அது அக்கிரமங்களினிமித்தமாகக் கூட்டப்பட்டு, தேவதூதரைக்கொண்டு மத்தியஸ்தன் கையிலே கட்டளையிடப்பட்டது.", "en": "Wherefore then serveth the law? It was added because of transgressions, till the seed should come to whom the promise was made; and it was ordained by angels in the hand of a mediator."}, {"verse": 20, "start": 216.29, "end": 220.15, "ta": "மத்தியஸ்தன் ஒருவனுக்குரியவனல்ல, தேவனோ ஒருவர்.", "en": "Now a mediator is not a mediator of one, but God is one."}, {"verse": 21, "start": 220.15, "end": 234.9, "ta": "அப்படியானால், நியாயப்பிரமாணம் தேவனுடைய வாக்குத்தத்தங்களுக்கு விரோதமா? அல்லவே; உயிரைக் கொடுக்கத்தக்க நியாயப்பிரமாணம் அருளப்பட்டிருந்ததானால், நீதியானது நியாயப்பிரமாணத்தினால் உண்டாயிருக்குமே.", "en": "Is the law then against the promises of God? God forbid: for if there had been a law given which could have given life, verily righteousness should have been by the law."}, {"verse": 22, "start": 234.9, "end": 248.17, "ta": "அப்படியிராதபடியால், இயேசுகிறிஸ்துவைப் பற்றும் விசுவாசத்தினாலே பலிக்கிற வாக்குத்தத்தம் விசுவாசமுள்ளவர்களுக்கு அளிக்கப்படும்படி வேதம் எல்லாரையும் ஏகமாய்ப் பாவத்தின்கீழ் அடைத்துப்போட்டது.", "en": "But the scripture hath concluded all under sin, that the promise by faith of Jesus Christ might be given to them that believe."}, {"verse": 23, "start": 248.17, "end": 259.21, "ta": "ஆதலால் விசுவாசம் வருகிறதற்குமுன்னே, வெளிப்படப்போகிற விசுவாசத்திற்கு ஏதுவாக நாம் அடைக்கப்பட்டவர்களாய் நியாயப்பிரமாணத்தின்கீழ் காவல் பண்ணப்பட்டிருந்தோம்.", "en": "But before faith came, we were kept under the law, shut up unto the faith which should afterwards be revealed."}, {"verse": 24, "start": 259.21, "end": 269.09, "ta": "இவ்விதமாக, நாம் விசுவாசத்திலே நீதிமான்களாக்கப்படுவதற்கு நியாயப்பிரமாணம் நம்மைக் கிறிஸ்துவினிடத்தில் வழிநடத்துகிற உபாத்தியாய் இருந்தது.", "en": "Wherefore the law was our schoolmaster to bring us unto Christ, that we might be justified by faith."}, {"verse": 25, "start": 269.09, "end": 273.49, "ta": "விசுவாசம் வந்தபின்பு நாம் உபாத்திக்குக் கீழானவர்களல்லவே.", "en": "But after that faith is come, we are no longer under a schoolmaster."}, {"verse": 26, "start": 273.49, "end": 280.33, "ta": "நீங்களெல்லாரும் கிறிஸ்து இயேசுவைப்பற்றும் விசுவாசத்தினால் தேவனுடைய புத்திரராயிருக்கிறீர்களே.", "en": "For ye are all the children of God by faith in Christ Jesus."}, {"verse": 27, "start": 280.33, "end": 289.46, "ta": "ஏனெனில், உங்களில் கிறிஸ்துவுக்குள்ளாக, ஞானஸ்நானம் பெற்றவர்கள் எத்தனைபேரோ அத்தனைபேரும் கிறிஸ்துவைத் தரித்துக்கொண்டீர்களே.", "en": "For as many of you as have been baptized into Christ have put on Christ."}, {"verse": 28, "start": 289.46, "end": 301.45, "ta": "யூதனென்றும் கிரேக்கனென்றுமில்லை, அடிமையென்றும் சுயாதீனனென்றுமில்லை, ஆணென்றும் பெண்ணென்றுமில்லை; நீங்களெல்லாரும் கிறிஸ்து இயேசுவுக்குள் ஒன்றாயிருக்கிறீர்கள்.", "en": "There is neither Jew nor Greek, there is neither bond nor free, there is neither male nor female: for ye are all one in Christ Jesus."}, {"verse": 29, "start": 301.45, "end": 310.11, "ta": "நீங்கள் கிறிஸ்துவினுடையவர்களானால், ஆபிரகாமின் சந்ததியாராயும், வாக்குத்தத்தத்தின்படியே சுதந்தரராயுமிருக்கிறீர்கள்.", "en": "And if ye be Christ’s, then are ye Abraham’s seed, and heirs according to the promise."}]}, "4": {"chapter": 4, "duration": 291.6, "audio_url": "audio_nt/B09_04.mp3", "total_verses": 31, "verses": [{"verse": 1, "start": 3.8, "end": 16.17, "ta": "பின்னும் நான் சொல்லுகிறதென்னவெனில், சுதந்தரவாளியானவன் எல்லாவற்றிற்கும் எஜமானாயிருந்தும், அவன் சிறுபிள்ளையாயிருக்குங்காலமளவும், அவனுக்கும் அடிமையானவனுக்கும் வித்தியாசமில்லை.", "en": "Now I say, That the heir, as long as he is a child, differeth nothing from a servant, though he be lord of all;"}, {"verse": 2, "start": 16.17, "end": 23.6, "ta": "தகப்பன் குறித்த காலம்வரைக்கும் அவன் காரியக்காரருக்கும் வீட்டு விசாரணைக்காரருக்கும் கீழ்ப்பட்டிருக்கிறான்.", "en": "But is under tutors and governors until the time appointed of the father."}, {"verse": 3, "start": 23.6, "end": 30.96, "ta": "அப்படியே நாமும் சிறுபிள்ளைகளாயிருந்த காலத்தில் இவ்வுலகத்தின் வழிபாடுகளுக்கு அடிமைப்பட்டவர்களாயிருந்தோம்.", "en": "Even so we, when we were children, were in bondage under the elements of the world:"}, {"verse": 4, "start": 30.96, "end": 37.54, "ta": "நாம் புத்திரசுவிகாரத்தையடையும்படி நியாயப்பிரமாணத்திற்குக் கீழ்ப்பட்டவர்களை மீட்டுக்கொள்ளத்தக்கதாக,", "en": "But when the fulness of the time was come, God sent forth his Son, made of a woman, made under the law,"}, {"verse": 5, "start": 37.54, "end": 46.39, "ta": "காலம் நிறைவேறினபோது, ஸ்திரீயினிடத்திற் பிறந்தவரும் நியாயப்பிரமாணத்திற்குக் கீழானவருமாகிய தம்முடைய குமாரனை தேவன் அனுப்பினார்.", "en": "To redeem them that were under the law, that we might receive the adoption of sons."}, {"verse": 6, "start": 46.39, "end": 56.62, "ta": "மேலும் நீங்கள் புத்திரராயிருக்கிறபடியினால், அப்பா, பிதாவே! என்று கூப்பிடத்தக்கதாக தேவன் தமது குமாரனுடைய ஆவியை உங்கள் இருதயங்களில் அனுப்பினார்.", "en": "And because ye are sons, God hath sent forth the Spirit of his Son into your hearts, crying, Abba, Father."}, {"verse": 7, "start": 56.62, "end": 65.74, "ta": "ஆகையால் இனி நீ அடிமையாயிராமல் புத்திரனாயிருக்கிறாய்; நீ புத்திரனேயானால், கிறிஸ்துமூலமாய் தேவனுடைய சுதந்தரனாயுமிருக்கிறாய்.", "en": "Wherefore thou art no more a servant, but a son; and if a son, then an heir of God through Christ."}, {"verse": 8, "start": 65.74, "end": 72.57, "ta": "நீங்கள் தேவனை அறியாமலிருந்தபோது, சுபாவத்தின்படி தேவர்களல்லாதவர்களுக்கு அடிமைகளாயிருந்தீர்கள்.", "en": "Howbeit then, when ye knew not God, ye did service unto them which by nature are no gods."}, {"verse": 9, "start": 72.57, "end": 86.9, "ta": "இப்பொழுதோ நீங்கள் தேவனை அறிந்திருக்க, அல்லது தேவனாலே அறியப்பட்டிருக்க, பெலனற்றதும் வெறுமையானதுமான அவ்வழிபாடுகளுக்கு நீங்கள் மறுபடியும் திரும்பி, மறுபடியும் அவைகளுக்கு அடிமைப்படும்படி விரும்புகிறதெப்படி?", "en": "But now, after that ye have known God, or rather are known of God, how turn ye again to the weak and beggarly elements, whereunto ye desire again to be in bondage?"}, {"verse": 10, "start": 86.9, "end": 92.63, "ta": "நாட்களையும், மாதங்களையும், காலங்ளையும், வருஷங்களையும் பார்க்கிறீர்களே.", "en": "Ye observe days, and months, and times, and years."}, {"verse": 11, "start": 92.63, "end": 99.28, "ta": "நான் உங்களுக்காகப் பிரயாசப்பட்டது வீணாய்ப்போயிற்றோ என்று உங்களைக்குறித்துப் பயந்திருக்கிறேன்.", "en": "I am afraid of you, lest I have bestowed upon you labour in vain."}, {"verse": 12, "start": 99.28, "end": 109.31, "ta": "சகோதரர் என்னைப்போலாகுங்கள் என்று உங்களை வேண்டிக்கொள்ளுகிறேன்; நான் உங்களைப்போலுமானேனே. எனக்கு நீங்கள் அநியாயம் ஒன்றும்செய்யவில்லை.", "en": "Brethren, I beseech you, be as I am ; for I am as ye are : ye have not injured me at all."}, {"verse": 13, "start": 109.31, "end": 117.19, "ta": "உங்களுக்குத் தெரிந்திருக்கிறபடி, நான் சரீர பலவீனத்தோடு முதலாந்தரம் உங்களுக்குச் சுவிசேஷத்தைப் பிரசங்கித்தேன்.", "en": "Ye know how through infirmity of the flesh I preached the gospel unto you at the first."}, {"verse": 14, "start": 117.19, "end": 129.24, "ta": "அப்படியிருந்தும் என் சரீரத்திலுண்டாயிருக்கிற சோதனையை நீங்கள் அசட்டைபண்ணாமலும், அரோசியாமலும், தேவதூதனைப்போலவும், கிறிஸ்து இயேசுவைப்போலவும், என்னை ஏற்றுக்கொண்டீர்கள்.", "en": "And my temptation which was in my flesh ye despised not, nor rejected; but received me as an angel of God, even as Christ Jesus."}, {"verse": 15, "start": 129.24, "end": 142.0, "ta": "அப்பொழுது நீங்கள் கொண்டிருந்த ஆனந்த பாக்கியம் எங்கே? உங்கள் கண்களைப் பிடுங்கி எனக்குக் கொடுக்கக்கூடுமானால், அப்படியும் செய்திருப்பீர்களென்று உங்களுக்குச் சாட்சியாயிருக்கிறேன்.", "en": "Where is then the blessedness ye spake of? for I bear you record, that, if it had been possible, ye would have plucked out your own eyes, and have given them to me."}, {"verse": 16, "start": 142.0, "end": 147.15, "ta": "நான் உங்களுக்குச் சத்தியத்தைச் சொன்னதினாலே உங்களுக்குச் சத்துருவானேனோ?", "en": "Am I therefore become your enemy, because I tell you the truth?"}, {"verse": 17, "start": 147.15, "end": 159.78, "ta": "அவர்கள் உங்களை நாடி வைராக்கியம் பாராட்டுகிறார்கள், ஆகிலும் நல்மனதோடே அப்படிச் செய்யாமல், நீங்கள் அவர்களை நாடி வைராக்கியம் பாராட்டும்பொருட்டு உங்களைப் புறம்பாக்க விரும்புகிறார்கள்.", "en": "They zealously affect you, but not well; yea, they would exclude you, that ye might affect them."}, {"verse": 18, "start": 159.78, "end": 169.29, "ta": "நல்விஷயத்தில் வைராக்கியம் பராட்டுவது நல்லதுதான்; அதை நான் உங்களிடத்தில் இருக்கும்பொழுதுமாத்திரமல்ல, எப்பொழுதும் பாராட்டவேண்டும்.", "en": "But it is good to be zealously affected always in a good thing , and not only when I am present with you."}, {"verse": 19, "start": 169.29, "end": 176.71, "ta": "என் சிறுபிள்ளைகளே, கிறிஸ்து உங்களிடத்தில் உருவாகுமளவும் உங்களுக்காக மறுபடியும் கர்ப்பவேதனைப்படுகிறேன்.", "en": "My little children, of whom I travail in birth again until Christ be formed in you,"}, {"verse": 20, "start": 176.71, "end": 185.44, "ta": "உங்களைக்குறித்து நான் சந்தேகப்படுகிறபடியால், நான் இப்பொழுது உங்களிடத்தில் வந்திருந்து, வேறுவகையாகப் பேச விரும்புகிறேன்.", "en": "I desire to be present with you now, and to change my voice; for I stand in doubt of you."}, {"verse": 21, "start": 185.44, "end": 195.14, "ta": "நியாயப்பிரமாணத்திற்குக் கீழ்ப்பட்டிருக்க விரும்புகிற நீங்கள் நியாயப்பிரமாணம் சொல்லுகிறதைக் கேட்கவில்லையா? இதை எனக்குச் சொல்லுங்கள்.", "en": "Tell me, ye that desire to be under the law, do ye not hear the law?"}, {"verse": 22, "start": 195.14, "end": 205.56, "ta": "ஆபிரகாமுக்கு இரண்டு குமாரர் இருந்தார்கள் என்று எழுதியிருக்கிறது; ஒருவன் அடிமையானவளிடத்தில் பிறந்தவன், ஒருவன் சுயாதீனமுள்ளவளிடத்தில் பிறந்தவன்.", "en": "For it is written, that Abraham had two sons, the one by a bondmaid, the other by a freewoman."}, {"verse": 23, "start": 205.56, "end": 214.16, "ta": "அடிமையானவளிடத்தில் பிறந்தவன் மாம்சத்தின்படி பிறந்தான், சுயாதீனமுள்ளவளிடத்தில் பிறந்தவன் வாக்குத்தத்தத்தின்படி பிறந்தான்.", "en": "But he who was of the bondwoman was born after the flesh; but he of the freewoman was by promise."}, {"verse": 24, "start": 214.16, "end": 226.8, "ta": "இவைகள் ஞான அர்த்தமுள்ளவைகள்; அந்த ஸ்திரீகள் இரண்டு ஏற்பாடுகளாம்; ஒன்று சீனாய்மலையிலுண்டான ஏற்பாடு, அது அடிமைத்தனத்திற்குள்ளாகப் பிள்ளைபெறுகிறது, அது ஆகார் என்பவள்தானே.", "en": "Which things are an allegory: for these are the two covenants; the one from the mount Sinai, which gendereth to bondage, which is Agar."}, {"verse": 25, "start": 226.8, "end": 237.02, "ta": "ஆகார் என்பது அரபிதேசத்திலுள்ள சீனாய்மலை; அந்த ஆகார் இப்பொழுதிருக்கிற எருசலேமுக்குச் சரி; இவள் தன் பிள்ளைகளோடேகூட அடிமைப்பட்டிருக்கிறாளே.", "en": "For this Agar is mount Sinai in Arabia, and answereth to Jerusalem which now is, and is in bondage with her children."}, {"verse": 26, "start": 237.02, "end": 241.97, "ta": "மேலான எருசலேமோ சுயாதீனமுள்ளவள், அவளே நம்மெல்லாருக்கும் தாயானவள்.", "en": "But Jerusalem which is above is free, which is the mother of us all."}, {"verse": 27, "start": 241.97, "end": 255.45, "ta": "அந்தப்படி பிள்ளைபெறாத மலடியே, மகிழ்ந்திரு; கர்ப்பவேதனைப்படாதவளே, களிப்பாய் எழும்பி ஆர்ப்பரி; புருஷனுள்ளவளைப் பார்க்கிலும் அநாத ஸ்திரீக்கே அதிக பிள்ளைகளுண்டு என்று எழுதியிருக்கிறது.", "en": "For it is written, Rejoice, thou barren that bearest not; break forth and cry, thou that travailest not: for the desolate hath many more children than she which hath an husband."}, {"verse": 28, "start": 255.45, "end": 260.4, "ta": "சகோதரரே நாம் ஈசாக்கைப்போல வாக்குத்தத்தத்துப் பிள்ளைகளாயிருக்கிறோம்.", "en": "Now we, brethren, as Isaac was, are the children of promise."}, {"verse": 29, "start": 260.4, "end": 268.61, "ta": "ஆகிலும் மாம்சத்தின்படி பிறந்தவன் ஆவியின்படி பிறந்தவனை அப்பொழுது துன்பப்படுத்தினது போல, இப்பொழுதும் நடந்துவருகிறது.", "en": "But as then he that was born after the flesh persecuted him that was born after the Spirit, even so it is now."}, {"verse": 30, "start": 268.61, "end": 281.96, "ta": "அதைக்குறித்து வேதம் என்னசொல்லுகிறது: அடிமையானவளின் மகன் சுயாதீனமுள்ளவளுடைய குமாரனோடே சுதந்தரவாளியாயிருப்பதில்லை; ஆகையால் அடிமையானவளையும், அவளுடைய மகனையும் புறம்பே தள்ளு என்று சொல்லுகிறது.", "en": "Nevertheless what saith the scripture? Cast out the bondwoman and her son: for the son of the bondwoman shall not be heir with the son of the freewoman."}, {"verse": 31, "start": 281.96, "end": 290.1, "ta": "இப்படியிருக்க, சகோதரரே, நாம் அடிமையானவளுக்குப் பிள்ளைகளாயிராமல், சுயாதீனமுள்ளவளுக்கே பிள்ளைகளாயிருக்கிறோம்.", "en": "So then, brethren, we are not children of the bondwoman, but of the free."}]}, "5": {"chapter": 5, "duration": 233.1, "audio_url": "audio_nt/B09_05.mp3", "total_verses": 26, "verses": [{"verse": 1, "start": 3.8, "end": 13.7, "ta": "ஆனபடியினாலே, நீங்கள் மறுபடியும் அடிமைத்தனத்தின் நுகத்துக்குட்படாமல், கிறிஸ்து நமக்கு உண்டாக்கின சுயாதீன நிலைமையிலே நிலைகொண்டிருங்கள்.", "en": "Stand fast therefore in the liberty wherewith Christ hath made us free, and be not entangled again with the yoke of bondage."}, {"verse": 2, "start": 13.7, "end": 23.47, "ta": "இதோ, நீங்கள் விருத்தசேதனம்பண்ணிக்கொண்டால் கிறிஸ்துவினால் உங்களுக்கு ஒரு பிரயோஜனமுமிராது என்று பவுலாகிய நான் உங்களுக்குச் சொல்லுகிறேன்.", "en": "Behold, I Paul say unto you, that if ye be circumcised, Christ shall profit you nothing."}, {"verse": 3, "start": 23.47, "end": 36.11, "ta": "மேலும், விருத்தசேதனம்பண்ணிக்கொள்ளுகிற எந்த மனுஷனும் நியாயப்பிரமாணம் முழுவதையும் நிறைவேற்றக் கடனாளியாயிருக்கிறான் என்று மறுபடியும் அப்படிப்பட்டவனுக்குச் சாட்சியாகச் சொல்லுகிறேன்.", "en": "For I testify again to every man that is circumcised, that he is a debtor to do the whole law."}, {"verse": 4, "start": 36.11, "end": 44.74, "ta": "நியாயப்பிரமாணத்தினால் நீதிமான்களாக விரும்புகிற நீங்கள் யாவரும் கிறிஸ்துவைவிட்டுப் பிரிந்து கிருபையினின்று விழுந்தீர்கள்.", "en": "Christ is become of no effect unto you, whosoever of you are justified by the law; ye are fallen from grace."}, {"verse": 5, "start": 44.74, "end": 51.23, "ta": "நாங்களோ நீதிகிடைக்குமென்று ஆவியைக்கொண்டு விசுவாசத்தினால் நம்பிக்கையோடே காத்திருக்கிறோம்.", "en": "For we through the Spirit wait for the hope of righteousness by faith."}, {"verse": 6, "start": 51.23, "end": 60.53, "ta": "கிறிஸ்து இயேசுவினிடத்தில் விருத்தசேதனமும் விருத்தசேதனமில்லாமையும் ஒன்றுக்கும் உதவாது, அன்பினால் கிரியைசெய்கிற விசுவாசமே உதவும்.", "en": "For in Jesus Christ neither circumcision availeth any thing, nor uncircumcision; but faith which worketh by love."}, {"verse": 7, "start": 60.53, "end": 67.76, "ta": "நீங்கள் நன்றாய் ஓடினீர்களே; சத்தியத்திற்குக் கீழ்ப்படியாமற்போக உங்களுக்குத் தடைசெய்தவன் யார்?", "en": "Ye did run well; who did hinder you that ye should not obey the truth?"}, {"verse": 8, "start": 67.76, "end": 71.24, "ta": "இந்தப் போதனை உங்களை அழைத்தவரால் உண்டானதல்ல.", "en": "This persuasion cometh not of him that calleth you."}, {"verse": 9, "start": 71.24, "end": 75.92, "ta": "புளிப்புள்ள கொஞ்சமாவானது பிசைந்த மாவனைத்தையும் உப்பப்பண்ணும்.", "en": "A little leaven leaveneth the whole lump."}, {"verse": 10, "start": 75.92, "end": 89.43, "ta": "நீங்கள் வேறுவிதமாய்ச் சிந்திக்கமாட்டீர்களென்று நான் கர்த்தருக்குள் உங்களைக்குறித்து நம்பிக்கையாயிருக்கிறேன்; உங்களைக் கலக்குகிறவன் எப்படிப்பட்டவனாயிருந்தாலும் தனக்கேற்ற ஆக்கினையை அடைவான்.", "en": "I have confidence in you through the Lord, that ye will be none otherwise minded: but he that troubleth you shall bear his judgment, whosoever he be."}, {"verse": 11, "start": 89.43, "end": 102.15, "ta": "சகோதரரே, இதுவரைக்கும் நான் விருத்தசேதனத்தைப் பிரசங்கிக்கிறவனாயிருந்தால், இதுவரைக்கும் என்னத்திற்குத் துன்பப்படுகிறேன்? அப்படியானால் சிலுவையைப்பற்றி வரும் இடறல் ஒழிந்திருக்குமே", "en": "And I, brethren, if I yet preach circumcision, why do I yet suffer persecution? then is the offence of the cross ceased."}, {"verse": 12, "start": 102.15, "end": 106.63, "ta": "உங்களைக் கலக்குகிறவர்கள் தறிப்புண்டுபோனால் நலமாயிருக்கும்.", "en": "I would they were even cut off which trouble you."}, {"verse": 13, "start": 106.63, "end": 118.27, "ta": "சகோதரரே, நீங்கள் சுயாதீனத்திற்கு அழைக்கப்பட்டீர்கள், இந்தச் சுயாதீனத்தை நீங்கள் மாம்சத்திற்கேதுவாக அநுசரியாமல், அன்பினாலே ஒருவருக்கொருவர் ஊழியஞ்செய்யுங்கள்.", "en": "For, brethren, ye have been called unto liberty; only use not liberty for an occasion to the flesh, but by love serve one another."}, {"verse": 14, "start": 118.27, "end": 127.84, "ta": "உன்னிடத்தில் நீ அன்புகூருவதுபோலப் பிறனிடத்திலும் அன்புகூருவாயாக, என்கிற இந்த ஒரே வார்த்தையிலே நியாயப்பிரமாணம் முழுவதும் நிறைவேறும்.", "en": "For all the law is fulfilled in one word, even in this; Thou shalt love thy neighbour as thyself."}, {"verse": 15, "start": 127.84, "end": 137.47, "ta": "நீங்கள் ஒருவரையொருவர் கடித்துப் பட்சித்தீர்களானால் அழிவீர்கள். அப்படி ஒருவராலொருவர் அழிக்கப்படாதபடிக்கு எச்சரிக்கையாயிருங்கள்.", "en": "But if ye bite and devour one another, take heed that ye be not consumed one of another."}, {"verse": 16, "start": 137.47, "end": 146.43, "ta": "பின்னும் நான் சொல்லுகிறதென்னவென்றால், ஆவிக்கேற்றபடி நடந்துகொள்ளுங்கள், அப்பொழுது மாம்ச இச்சையை நிறைவேற்றாதிருப்பீர்கள்.", "en": "This I say then, Walk in the Spirit, and ye shall not fulfil the lust of the flesh."}, {"verse": 17, "start": 146.43, "end": 159.28, "ta": "மாம்சம் ஆவிக்கு விரோதமாகவும், ஆவி மாம்சத்துக்கு விரோதமாகவும் இச்சிக்கிறது; நீங்கள் செய்யவேண்டுமென்றிருக்கிறவைகளைச் செய்யாதபடிக்கு, இவைகள் ஒன்றுக்கொன்று விரோதமாயிருக்கிறது.", "en": "For the flesh lusteth against the Spirit, and the Spirit against the flesh: and these are contrary the one to the other: so that ye cannot do the things that ye would."}, {"verse": 18, "start": 159.28, "end": 165.7, "ta": "ஆவியினால் நடத்தப்படுவீர்களானால், நீங்கள் நியாயப்பிரமாணத்திற்குக் கீழ்ப்பட்டவர்களல்ல.", "en": "But if ye be led of the Spirit, ye are not under the law."}, {"verse": 19, "start": 165.7, "end": 173.33, "ta": "மாம்சத்தின் கிரியைகள் வெளியரங்கமாயிருக்கின்றன, அவையாவன: விபசாரம், வேசித்தனம், அசுத்தம், காமவிகாரம்,", "en": "Now the works of the flesh are manifest, which are these ; Adultery, fornication, uncleanness, lasciviousness,"}, {"verse": 20, "start": 173.33, "end": 182.9, "ta": "விக்கிரகாராதனை, பில்லிசூனியம், பகைகள், விரோதங்கள், வைராக்கியங்கள், கோபங்கள், சண்டைகள், பிரிவினைகள், மார்க்கபேதங்கள்,", "en": "Idolatry, witchcraft, hatred, variance, emulations, wrath, strife, seditions, heresies,"}, {"verse": 21, "start": 182.9, "end": 197.55, "ta": "பொறாமைகள், கொலைகள், வெறிகள், களியாட்டுகள் முதலானவைகளே; இப்படிப்பட்டவைகளைச் செய்கிறவர்கள் தேவனுடைய ராஜ்யத்தைச் சுதந்தரிப்பதில்லையென்று முன்னே நான் சொன்னதுபோல இப்பொழுதும் உங்களுக்குச் சொல்லுகிறேன்.", "en": "Envyings, murders, drunkenness, revellings, and such like: of the which I tell you before, as I have also told you in time past, that they which do such things shall not inherit the kingdom of God."}, {"verse": 22, "start": 197.55, "end": 204.57, "ta": "ஆவியின் கனியோ, அன்பு, சந்தோஷம், சமாதானம், நீடியபொறுமை, தயவு, நற்குணம், விசுவாசம்,", "en": "But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith,"}, {"verse": 23, "start": 204.57, "end": 210.79, "ta": "சாந்தம், இச்சையடக்கம்; இப்படிப்பட்டவைகளுக்கு விரோதமான பிரமாணம் ஒன்றுமில்லை.", "en": "Meekness, temperance: against such there is no law."}, {"verse": 24, "start": 210.79, "end": 217.95, "ta": "கிறிஸ்துவினுடையவர்கள் தங்கள் மாம்சத்தையும் அதின் ஆசை இச்சைகளையும் சிலுவையில் அறைந்திருக்கிறார்கள்.", "en": "And they that are Christ’s have crucified the flesh with the affections and lusts."}, {"verse": 25, "start": 217.95, "end": 223.04, "ta": "நாம் ஆவியினாலே பிழைத்திருந்தால், ஆவிக்கேற்றபடி நடக்கவும் கடவோம்.", "en": "If we live in the Spirit, let us also walk in the Spirit."}, {"verse": 26, "start": 223.04, "end": 231.6, "ta": "வீண் புகழ்ச்சியை விரும்பாமலும், ஒருவரையொருவர் கோபமூட்டாமலும், ஒருவர்மேல் ஒருவர் பொறாமைகொள்ளாமலும் இருக்கக்கடவோம்.", "en": "Let us not be desirous of vain glory, provoking one another, envying one another."}]}, "6": {"chapter": 6, "duration": 175.35, "audio_url": "audio_nt/B09_06.mp3", "total_verses": 18, "verses": [{"verse": 1, "start": 3.8, "end": 18.41, "ta": "சகோதரரே, ஒருவன் யாதொரு குற்றத்தில் அகப்பட்டால், ஆவிக்குரியவர்களாகிய நீங்கள் சாந்தமுள்ள ஆவியோடே அப்படிப்பட்டவனைச் சீர்பொருந்தப்பண்ணுங்கள்; நீயும் சோதிக்கப்படாதபடிக்கு உன்னைக்குறித்து எச்சரிக்கையாயிரு.", "en": "Brethren, if a man be overtaken in a fault, ye which are spiritual, restore such an one in the spirit of meekness; considering thyself, lest thou also be tempted."}, {"verse": 2, "start": 18.41, "end": 24.72, "ta": "ஒருவர் பாரத்தை ஒருவர் சுமந்து, அப்படியே கிறிஸ்துவினுடைய பிரமாணத்தை நிறைவேற்றுங்கள்.", "en": "Bear ye one another’s burdens, and so fulfil the law of Christ."}, {"verse": 3, "start": 24.72, "end": 32.56, "ta": "ஒருவன், தான் ஒன்றுமில்லாதிருந்தும், தன்னை ஒரு பொருட்டென்று எண்ணினால், தன்னைத்தானே வஞ்சிக்கிறவனாவான்.", "en": "For if a man think himself to be something, when he is nothing, he deceiveth himself."}, {"verse": 4, "start": 32.56, "end": 43.79, "ta": "அவனவன் தன்தன் சுயகிரியையைச் சோதித்துப்பார்க்கக்கடவன்; அப்பொழுது மற்றவனைப் பார்க்கும்போதல்ல, தன்னையே பார்க்கும்போது மேன்மைபாராட்ட அவனுக்கு இடமுண்டாகும்.", "en": "But let every man prove his own work, and then shall he have rejoicing in himself alone, and not in another."}, {"verse": 5, "start": 43.79, "end": 46.64, "ta": "அவனவன் தன்தன் பாரத்தைச் சுமப்பானே.", "en": "For every man shall bear his own burden."}, {"verse": 6, "start": 46.64, "end": 54.48, "ta": "மேலும், திருவசனத்தில் உபதேசிக்கப்படுகிறவன் உபதேசிக்கிறவனுக்குச் சகல நன்மைகளிலும் பகிர்ந்து கொடுக்கக்கடவன்.", "en": "Let him that is taught in the word communicate unto him that teacheth in all good things."}, {"verse": 7, "start": 54.48, "end": 62.06, "ta": "மோசம்போகாதிருங்கள், தேவன் தம்மைப் பரியாசம்பண்ணவொட்டார்; மனுஷன் எதை விதைக்கிறானோ அதையே அறுப்பான்.", "en": "Be not deceived; God is not mocked: for whatsoever a man soweth, that shall he also reap."}, {"verse": 8, "start": 62.06, "end": 71.29, "ta": "தன் மாம்சத்திற்கென்று விதைக்கிறவன் மாம்சத்தினால் அழிவை அறுப்பான்; ஆவிக்கென்று விதைக்கிறவன் ஆவியினாலே நித்தியஜீவனை அறுப்பான்.", "en": "For he that soweth to his flesh shall of the flesh reap corruption; but he that soweth to the Spirit shall of the Spirit reap life everlasting."}, {"verse": 9, "start": 71.29, "end": 78.73, "ta": "நன்மைசெய்கிறதில் சோர்ந்துபோகாமல் இருப்போமாக; நாம் தளர்ந்துபோகாதிருந்தால் ஏற்றகாலத்தில் அறுப்போம்.", "en": "And let us not be weary in well doing: for in due season we shall reap, if we faint not."}, {"verse": 10, "start": 78.73, "end": 88.09, "ta": "ஆகையால் நமக்குக் கிடைக்கும் சமயத்திற்குத்தக்கதாக, யாவருக்கும், விசேஷமாக விசுவாச குடும்பத்தார்களுக்கும், நன்மைசெய்யக்கடவோம்.", "en": "As we have therefore opportunity, let us do good unto all men , especially unto them who are of the household of faith."}, {"verse": 11, "start": 88.09, "end": 91.95, "ta": "என் கையெழுத்தாய் எவ்வளவு எழுதினேனென்று பாருங்கள்.", "en": "Ye see how large a letter I have written unto you with mine own hand."}, {"verse": 12, "start": 91.95, "end": 105.43, "ta": "மாம்சத்தின்படி நல்வேஷமாய்க் காணப்பட விரும்புகிறவர்கள் எவர்களோ, அவர்கள் தாங்கள் கிறிஸ்துவினுடைய சிலுவையினிமித்தம் துன்பப்படாதபடிக்கே உங்களை விருத்தசேதனம் பண்ணிக்கொள்ளக் கட்டாயம்பண்ணுகிறார்கள்.", "en": "As many as desire to make a fair shew in the flesh, they constrain you to be circumcised; only lest they should suffer persecution for the cross of Christ."}, {"verse": 13, "start": 105.43, "end": 121.77, "ta": "விருத்தசேதனம் அடைந்திருக்கிற அவர்களும் நியாயப்பிரமாணத்தைக் கைக்கொள்ளாமலிருக்கிறார்கள்; அப்படியிருந்தும், அவர்கள் உங்கள் மாம்சத்தைக்குறித்து மேன்மைபாராட்டும்படிக்கு நீங்கள் விருத்தசேதனம்பண்ணிக்கொள்ளவேண்டுமென்று விரும்புகிறார்கள்.", "en": "For neither they themselves who are circumcised keep the law; but desire to have you circumcised, that they may glory in your flesh."}, {"verse": 14, "start": 121.77, "end": 137.58, "ta": "நானோ நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவின் சிலுவையைக் குறித்தேயல்லாமல் வேறொன்றையுங் குறித்து மேன்மைபாராட்டாதிருப்பேனாக; அவரால் உலகம் எனக்குச் சிலுவையிலறையுண்டிருக்கிறது, நானும் உலகத்திற்குச் சிலுவையிலறையுண்டிருக்கிறேன்.", "en": "But God forbid that I should glory, save in the cross of our Lord Jesus Christ, by whom the world is crucified unto me, and I unto the world."}, {"verse": 15, "start": 137.58, "end": 146.28, "ta": "கிறிஸ்து இயேசுவுக்குள் விருத்தசேதனமும் ஒன்றுமில்லை, விருத்தசேதனமில்லாமையும் ஒன்றுமில்லை; புது சிருஷ்டியே காரியம்.", "en": "For in Christ Jesus neither circumcision availeth any thing, nor uncircumcision, but a new creature."}, {"verse": 16, "start": 146.28, "end": 156.05, "ta": "இந்தப் பிரமாணத்தின்படி நடந்துவருகிறவர்கள் எவர்களோ, அவர்களுக்கும், தேவனுடைய இஸ்ரவேலருக்கும், சமாதானமும் இரக்கமும் உண்டாயிருப்பதாக.", "en": "And as many as walk according to this rule, peace be on them, and mercy, and upon the Israel of God."}, {"verse": 17, "start": 156.05, "end": 166.41, "ta": "இனிமேல் ஒருவனும் எனக்கு வருத்தம் உண்டாக்காதிருப்பானாக; கர்த்தராகிய இயேசுவினுடைய அச்சடையாளங்களை நான் என் சரீரத்திலே தரித்துக்கொண்டிருக்கிறேன்.", "en": "From henceforth let no man trouble me: for I bear in my body the marks of the Lord Jesus."}, {"verse": 18, "start": 166.41, "end": 173.85, "ta": "சகோதரரே, நம்முடைய கர்த்தராகிய இயேசுகிறிஸ்துவின் கிருபை உங்கள் ஆவியுடனேகூட இருப்பதாக. ஆமென்.", "en": "Brethren, the grace of our Lord Jesus Christ be with your spirit. Amen."}]}}};
}
